-- بيانات مقرر فيزياء 3-2 (المقرر 104، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys32-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يتحرك إلكترون بسرعة $2.0\times10^{6}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.50 T كما في الشكل الآتي. ما مقدار القوة المغناطيسية المؤثرة فيه؟ (شحنة الإلكترون $q = -1.60\times10^{-19}\ \text{C}$)', null, '[{"src":"qimg/phys32/c3l2-o05-beam.svg","alt":"مجال مغناطيسي منتظم B داخل في الورقة تمثله رموز (×) خضراء. في وسطه إلكترون (دائرة زرقاء مكتوب تحتها «إلكترون») يخرج منه سهم أحمر للسرعة v يتجه إلى اليمين، أي عموديًّا على المجال."}]'::jsonb, '["$1.6\\times10^{-13}\\ \\text{N}$","$3.2\\times10^{-13}\\ \\text{N}$","$6.4\\times10^{-13}\\ \\text{N}$","$1.0\\times10^{6}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 89–90 — المثال 2 ومسائل تدريبية 21–24'),
('mcq', 2, 'يتحرك أيون ثنائي التأيّن (يحمل شحنتين أساسيتين موجبتين) بسرعة $4.0\times10^{4}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.080 T. ما مقدار القوة المؤثرة فيه؟ (الشحنة الأساسية $1.60\times10^{-19}\ \text{C}$)', null, null, '["$5.1\\times10^{-16}\\ \\text{N}$","$1.6\\times10^{-13}\\ \\text{N}$","$1.0\\times10^{-15}\\ \\text{N}$","$3.2\\times10^{3}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب مباشر', 'متوسط', 'الكتاب ص 90 — مسائل تدريبية السؤالان 22 و23'),
('mcq', 3, 'يتحرك إلكترون بسرعة $5.0\times10^{6}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم فيتأثر بقوة مقدارها $4.0\times10^{-13}\ \text{N}$. ما مقدار المجال المغناطيسي؟ (مقدار شحنة الإلكترون $1.60\times10^{-19}\ \text{C}$)', null, null, '["$2.0\\ \\text{T}$","$0.50\\ \\text{T}$","$3.2\\times10^{-25}\\ \\text{T}$","$2.5\\times10^{6}\\ \\text{T}$"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 103 — اختبار مقنن س4'),
('mcq', 4, 'يتحرك بروتون عموديًّا على مجال مغناطيسي منتظم مقداره 0.20 T فيتأثر بقوة مقدارها $6.4\times10^{-14}\ \text{N}$. ما مقدار سرعته؟ (شحنة البروتون $1.60\times10^{-19}\ \text{C}$)', null, null, '["$4.0\\times10^{5}\\ \\text{m/s}$","$8.0\\times10^{4}\\ \\text{m/s}$","$5.0\\times10^{-7}\\ \\text{m/s}$","$2.0\\times10^{6}\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'متوسط', 'الكتاب ص 100 — السؤال 83'),
('mcq', 5, 'أثّرت قوة مقدارها $6.4\times10^{-16}\ \text{N}$ في أيون يتحرك بسرعة $2.0\times10^{4}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.10 T. ما مقدار شحنة الأيون؟', null, null, '["$3.2\\times10^{-19}\\ \\text{C}$","$3.2\\times10^{-20}\\ \\text{C}$","$3.2\\times10^{-21}\\ \\text{C}$","$1.3\\times10^{-12}\\ \\text{C}$"]'::jsonb, 'تطبيق', 'حساب كمية مجهولة', 'صعب', 'الكتاب ص 100 — السؤال 85'),
('mcq', 6, 'يتحرك بروتون بسرعة $3.0\times10^{6}\ \text{m/s}$ في مجال مغناطيسي منتظم مقداره 0.40 T، واتجاه سرعته يصنع زاوية $30^\circ$ مع المجال كما في الشكل الآتي. ما مقدار القوة المغناطيسية المؤثرة فيه؟', null, '[{"src":"qimg/phys32/c3l2-o05-angle.svg","alt":"أربعة خطوط مجال مغناطيسي خضراء أفقية متوازية تتجه إلى اليمين ويرمز لها B. على أحدها بروتون (دائرة وردية بجانبها إشارة +) يخرج منه سهم أحمر للسرعة v يتجه إلى أعلى اليمين، والزاوية بين سهم السرعة وخط المجال مؤشر عليها بقوس وقيمتها 30°."}]'::jsonb, '["$1.7\\times10^{-13}\\ \\text{N}$","$1.9\\times10^{-13}\\ \\text{N}$","$9.6\\times10^{-14}\\ \\text{N}$","صفر $0\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب مع زاوية', 'متوسط', 'الكتاب ص 89 — F = qvB (sin θ)'),
('mcq', 7, 'يتحرك بروتون بسرعة $5.0\times10^{5}\ \text{m/s}$ في اتجاه خطوط مجال مغناطيسي منتظم مقداره 0.20 T (موازيًا لها). ما مقدار القوة المغناطيسية المؤثرة فيه؟', null, null, '["$1.6\\times10^{-14}\\ \\text{N}$","صفر $0\\ \\text{N}$","$1.0\\times10^{5}\\ \\text{N}$","$6.4\\times10^{-26}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب مباشر', 'سهل', 'الكتاب ص 89 — F = qvB (sin θ)'),
('essay', 1, 'يتحرك جسيم ألفا (ذرة هيليوم ثنائية التأين تحمل شحنتين أساسيتين موجبتين) بسرعة $6.0\times10^{4}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.040 T. (a) ما مقدار القوة المؤثرة فيه؟ (b) ما مقدار القوة المؤثرة في بروتون يتحرك بالسرعة نفسها في المجال نفسه؟ (الشحنة الأساسية $1.60\times10^{-19}\ \text{C}$)', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 90 — مسائل تدريبية السؤال 24'),
('essay', 2, 'يتحرك جسيم بيتا (إلكترون له سرعة كبيرة) بسرعة $2.5\times10^{7}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.40 T. (مقدار شحنة الإلكترون $1.60\times10^{-19}\ \text{C}$) (a) ما مقدار القوة المغناطيسية المؤثرة فيه؟ (b) إذا كانت كتلة الإلكترون $9.11\times10^{-31}\ \text{kg}$، فما مقدار التسارع الذي يكتسبه؟ (c) لماذا لا تؤثر قوة الجاذبية تأثيرًا يُذكر مقارنة بالقوة المغناطيسية؟ ($g = 9.80\ \text{m/s}^2$)', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 101 — السؤالان 88 و89'),
('essay', 3, 'أثرت قوة مقدارها $1.44\times10^{-15}\ \text{N}$ في أيون موجب مجهول الشحنة يتحرك بسرعة $3.0\times10^{4}\ \text{m/s}$ عموديًّا على مجال مغناطيسي منتظم مقداره 0.10 T. (a) ما مقدار شحنة الأيون؟ (b) كم شحنة أساسية يحمل؟ (c) إذا دخل الأيون نفسه المجال بالسرعة نفسها لكن في اتجاه يصنع زاوية $30^\circ$ مع المجال، فما مقدار القوة المؤثرة فيه؟', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 89، وص 100 السؤال 85')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'مقدار القوة: $F = qv\mathrm{B} = (1.60\times10^{-19}\ \text{C})(2.0\times10^{6}\ \text{m/s})(0.50\ \text{T}) = 1.6\times10^{-13}\ \text{N}$ (وإشارة الشحنة السالبة تخص اتجاه القوة لا مقدارها).', '["","إهمال المجال المغناطيسي: $qv$ فقط.","قسمة $qv$ على $\\mathrm{B}$ بدل الضرب فيه.","إهمال شحنة الإلكترون: $v\\mathrm{B}$ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.373Z"}'::jsonb),
('mcq', 2, 2, '$q = 2(1.60\times10^{-19}) = 3.20\times10^{-19}\ \text{C}$، و$F = qv\mathrm{B} = (3.20\times10^{-19})(4.0\times10^{4})(0.080) = 1.0\times10^{-15}\ \text{N}$.', '["استعمال شحنة أساسية واحدة بدل شحنتين.","قسمة $qv$ على $\\mathrm{B}$ بدل الضرب فيه.","","إهمال الشحنة في العلاقة: $v\\mathrm{B}$ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-28T06:03:18.374Z"}'::jsonb),
('mcq', 3, 1, '$\mathrm{B} = \frac{F}{qv} = \frac{4.0\times10^{-13}\ \text{N}}{(1.60\times10^{-19}\ \text{C})(5.0\times10^{6}\ \text{m/s})} = 0.50\ \text{T}$.', '["قلب العلاقة: $\\frac{qv}{F}$.","","ضرب القوة في $qv$ بدل القسمة عليه.","قسمة القوة على الشحنة فقط وإهمال السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-28T06:03:18.374Z"}'::jsonb),
('mcq', 4, 3, '$v = \frac{F}{q\mathrm{B}} = \frac{6.4\times10^{-14}\ \text{N}}{(1.60\times10^{-19}\ \text{C})(0.20\ \text{T})} = 2.0\times10^{6}\ \text{m/s}$.', '["إهمال المجال: قسمة القوة على الشحنة فقط.","ضرب $\\frac{F}{q}$ في $\\mathrm{B}$ بدل القسمة عليه.","قلب العلاقة: $\\frac{q\\mathrm{B}}{F}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-28T06:03:18.375Z"}'::jsonb),
('mcq', 5, 0, '$q = \frac{F}{v\mathrm{B}} = \frac{6.4\times10^{-16}\ \text{N}}{(2.0\times10^{4}\ \text{m/s})(0.10\ \text{T})} = 3.2\times10^{-19}\ \text{C}$، أي شحنتان أساسيتان ($\frac{3.2\times10^{-19}}{1.60\times10^{-19}} = 2$).', '["","قسمة القوة على السرعة فقط وإهمال المجال.","ضرب $\\frac{F}{v}$ في $\\mathrm{B}$ بدل القسمة عليه.","ضرب الكميات الثلاث $Fv\\mathrm{B}$ بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-28T06:03:18.375Z"}'::jsonb),
('mcq', 6, 2, '$F = qv\mathrm{B}\,(\sin\theta) = (1.60\times10^{-19})(3.0\times10^{6})(0.40)(\sin 30^\circ) = 1.92\times10^{-13} \times 0.50 = 9.6\times10^{-14}\ \text{N}$.', '["استعمال $\\cos 30^\\circ$ بدل $\\sin 30^\\circ$.","إهمال الزاوية وعدّ السرعة عمودية على المجال.","","السرعة ليست موازية للمجال، فالقوة لا تنعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.375Z"}'::jsonb),
('mcq', 7, 1, 'السرعة موازية للمجال فالزاوية $\theta = 0^\circ$، و$F = qv\mathrm{B}\,(\sin 0^\circ) = 0$.', '["هذه القوة لو كانت السرعة عمودية على المجال.","","إهمال الشحنة وإهمال أن السرعة موازية للمجال.","قسمة $q\\mathrm{B}$ على $v$، مع إهمال أن السرعة موازية للمجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-28T06:03:18.376Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $q = 2(1.60\times10^{-19}) = 3.20\times10^{-19}\ \text{C}$، و$F = qv\mathrm{B} = (3.20\times10^{-19})(6.0\times10^{4})(0.040) = 7.7\times10^{-16}\ \text{N}$. (b) شحنة البروتون نصف شحنة جسيم ألفا، فالقوة $F = (1.60\times10^{-19})(6.0\times10^{4})(0.040) = 3.8\times10^{-16}\ \text{N}$، أي نصف القوة المؤثرة في جسيم ألفا.', '["شحنة جسيم ألفا $3.20\\times10^{-19}\\ \\text{C}$","القوة على جسيم ألفا $7.7\\times10^{-16}\\ \\text{N}$","القوة على البروتون $3.8\\times10^{-16}\\ \\text{N}$ (النصف)"]'::jsonb, '["$q = 2 \\times (1.60\\times10^{-19}\\ \\text{C}) = 3.20\\times10^{-19}\\ \\text{C}$","$F = qv\\mathrm{B} = (3.20\\times10^{-19})(6.0\\times10^{4})(0.040) = 7.68\\times10^{-16} \\approx 7.7\\times10^{-16}\\ \\text{N}$","$F_p = (1.60\\times10^{-19})(6.0\\times10^{4})(0.040) = 3.84\\times10^{-16} \\approx 3.8\\times10^{-16}\\ \\text{N}$"]'::jsonb, '[{"element":"شحنة جسيم ألفا","marks":1},{"element":"القوة على جسيم ألفا","marks":1},{"element":"القوة على البروتون","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"القوة على جسيم ألفا صحيحة مع خطأ في (b)"},{"level":"1 درجة","description":"التعويض صحيح بشحنة أساسية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال شحنة أساسية واحدة لجسيم ألفا","خطأ في قوى الأس العشري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-28T06:03:18.376Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $F = qv\mathrm{B} = (1.60\times10^{-19})(2.5\times10^{7})(0.40) = 1.6\times10^{-12}\ \text{N}$. (b) $a = \frac{F}{m} = \frac{1.6\times10^{-12}\ \text{N}}{9.11\times10^{-31}\ \text{kg}} = 1.8\times10^{18}\ \text{m/s}^2$. (c) وزن الإلكترون $mg = (9.11\times10^{-31})(9.80) \approx 8.9\times10^{-30}\ \text{N}$، وهو أصغر من القوة المغناطيسية بنحو $10^{17}$ مرة، فيُهمل.', '["القوة $1.6\\times10^{-12}\\ \\text{N}$","التسارع $1.8\\times10^{18}\\ \\text{m/s}^2$","مقارنة الوزن بالقوة المغناطيسية"]'::jsonb, '["$F = qv\\mathrm{B} = (1.60\\times10^{-19})(2.5\\times10^{7})(0.40) = 1.6\\times10^{-12}\\ \\text{N}$","$a = \\frac{F}{m} = \\frac{1.6\\times10^{-12}}{9.11\\times10^{-31}} = 1.76\\times10^{18} \\approx 1.8\\times10^{18}\\ \\text{m/s}^2$","$F_g = mg = (9.11\\times10^{-31})(9.80) = 8.9\\times10^{-30}\\ \\text{N}$"]'::jsonb, '[{"element":"حساب القوة","marks":2},{"element":"حساب التسارع","marks":1},{"element":"المقارنة بالوزن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"القوة صحيحة مع خطأ في التسارع أو المقارنة"},{"level":"1 درجة","description":"العلاقة صحيحة مع خطأ حسابي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الكتلة على القوة","خطأ في جمع الأسس عند القسمة","إدخال إشارة الشحنة السالبة في مقدار التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-28T06:03:18.377Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $q = \frac{F}{v\mathrm{B}} = \frac{1.44\times10^{-15}}{(3.0\times10^{4})(0.10)} = 4.8\times10^{-19}\ \text{C}$. (b) عدد الشحنات $= \frac{4.8\times10^{-19}}{1.60\times10^{-19}} = 3$ شحنات أساسية. (c) $F = qv\mathrm{B}\,(\sin 30^\circ) = 1.44\times10^{-15} \times 0.50 = 7.2\times10^{-16}\ \text{N}$.', '["الشحنة $4.8\\times10^{-19}\\ \\text{C}$","ثلاث شحنات أساسية","القوة عند $30^\\circ$ = $7.2\\times10^{-16}\\ \\text{N}$"]'::jsonb, '["$q = \\frac{F}{v\\mathrm{B}} = \\frac{1.44\\times10^{-15}}{3.0\\times10^{3}} = 4.8\\times10^{-19}\\ \\text{C}$","عدد الشحنات الأساسية $= \\frac{4.8\\times10^{-19}}{1.60\\times10^{-19}} = 3$","$F = qv\\mathrm{B}\\,(\\sin 30^\\circ) = (1.44\\times10^{-15})(0.50) = 7.2\\times10^{-16}\\ \\text{N}$"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب القوة في vB بدل القسمة","استعمال $\\cos 30^\\circ$ في الجزء (c)","عدّ الشحنة عددًا غير صحيح من الشحنات الأساسية دون مراجعة الحساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.377Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O05') and x.type = v.type and x.number = v.number
