insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يسري تيار إلى اليمين في سلك مستقيم موضوع في مجال مغناطيسي داخل في الورقة كما في الشكل الآتي. ما اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-a.svg","alt":"سلك مستقيم أفقي في مجال مغناطيسي منتظم B داخل في الورقة تمثله رموز (×) خضراء، وفوق السلك سهم التيار I يتجه إلى اليمين."}]'::jsonb, '["إلى أسفل الصفحة","إلى داخل الورقة","إلى أعلى الصفحة","إلى خارج الورقة"]'::jsonb, 'تطبيق', 'تحديد اتجاه القوة', 'سهل', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)'),
('mcq', 2, 'يسري تيار إلى أعلى الصفحة في سلك رأسي موضوع في مجال مغناطيسي خارج من الورقة كما في الشكل الآتي. ما اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-b.svg","alt":"سلك مستقيم رأسي في مجال مغناطيسي منتظم B خارج من الورقة تمثله نقاط خضراء، وبجانب السلك سهم التيار I يتجه إلى أعلى الصفحة."}]'::jsonb, '["إلى يمين الصفحة","إلى يسار الصفحة","إلى داخل الورقة","إلى خارج الورقة"]'::jsonb, 'تطبيق', 'تحديد اتجاه القوة', 'سهل', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)'),
('mcq', 3, 'يبين الشكل الآتي مقطع سلك عمودي على الورقة يسري فيه تيار خارج من الورقة (•)، وهو موضوع في مجال مغناطيسي منتظم يتجه إلى يسار الصفحة. ما اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-c.svg","alt":"خمسة خطوط مجال مغناطيسي خضراء أفقية تتجه إلى يسار الصفحة ويرمز لها B. في وسطها مقطع دائري لسلك عمودي على الورقة في داخله نقطة (•) تعني أن التيار I خارج من الورقة."}]'::jsonb, '["إلى أعلى الصفحة","إلى أسفل الصفحة","إلى يسار الصفحة","إلى يمين الصفحة"]'::jsonb, 'تطبيق', 'تحديد اتجاه القوة', 'متوسط', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)، وص 83–84 المثال 1'),
('mcq', 4, 'يمر سلك أفقي يسري فيه تيار إلى اليمين بين قطبي مغناطيس؛ القطب الشمالي N فوقه والقطب الجنوبي S تحته، كما في الشكل الآتي. ما اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-d.svg","alt":"قطب مغناطيسي شمالي N في أعلى الشكل وقطب جنوبي S في أسفله، وبينهما خطوط مجال خضراء رأسية تتجه إلى أسفل الصفحة من N إلى S. يمر بينهما سلك أفقي، وفوق طرفه الأيسر سهم التيار I يتجه إلى اليمين."}]'::jsonb, '["إلى داخل الورقة","إلى أعلى الصفحة","إلى خارج الورقة","إلى أسفل الصفحة"]'::jsonb, 'تحليل', 'تحديد اتجاه القوة', 'صعب', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)، والشكل 16-3'),
('mcq', 5, 'يتحرك بروتون إلى أعلى الصفحة في مجال مغناطيسي داخل في الورقة كما في الشكل الآتي. ما اتجاه القوة المغناطيسية المؤثرة فيه لحظة مروره بالموضع المبين؟', null, '[{"src":"qimg/phys32/c3l2-o06-e.svg","alt":"مجال مغناطيسي منتظم B داخل في الورقة تمثله رموز (×) خضراء. في أسفله بروتون (دائرة وردية بجانبها إشارة + ومكتوب تحتها «بروتون») يخرج منه سهم أحمر للسرعة v يتجه إلى أعلى الصفحة."}]'::jsonb, '["إلى يمين الصفحة","إلى خارج الورقة","إلى يسار الصفحة","إلى أسفل الصفحة"]'::jsonb, 'تطبيق', 'تحديد اتجاه القوة', 'متوسط', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('mcq', 6, 'يسري تيار إلى أسفل الصفحة في سلك رأسي موضوع في مجال مغناطيسي منتظم يتجه إلى يسار الصفحة كما في الشكل الآتي. ما اتجاه القوة المغناطيسية المؤثرة في السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-f.svg","alt":"أربعة خطوط مجال مغناطيسي خضراء أفقية تتجه إلى يسار الصفحة ويرمز لها B، ويقطعها سلك رأسي، وبجانب السلك سهم التيار I يتجه إلى أسفل الصفحة."}]'::jsonb, '["إلى خارج الورقة","إلى يسار الصفحة","إلى يمين الصفحة","إلى داخل الورقة"]'::jsonb, 'تطبيق', 'تحديد اتجاه القوة', 'متوسط', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)'),
('mcq', 7, 'يسري تيار إلى أسفل الصفحة في سلك رأسي، فيتأثر بقوة مغناطيسية إلى يسار الصفحة كما في الشكل الآتي. ما اتجاه المجال المغناطيسي المسبّب لهذه القوة، إذا كان عموديًّا على السلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-g.svg","alt":"سلك رأسي، وعلى يمينه سهم التيار I يتجه إلى أسفل الصفحة، ومن نقطة على السلك سهم أزرق للقوة F يتجه إلى يسار الصفحة. وتحت الشكل عبارة «اتجاه المجال المغناطيسي ؟»."}]'::jsonb, '["إلى داخل الورقة","إلى يسار الصفحة","إلى خارج الورقة","إلى أسفل الصفحة"]'::jsonb, 'تحليل', 'تحديد اتجاه المجال', 'صعب', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)'),
('essay', 1, 'سلك أفقي يمتد من الشرق إلى الغرب، ويسري فيه تيار نحو الغرب. المركّبة الأفقية للمجال المغناطيسي الأرضي في موقع السلك تتجه نحو الشمال، وهي عمودية على السلك. (a) ارسم مخططًا من أعلى (منظرًا علويًّا) يبين اتجاهي التيار والمجال. (b) استخدم القاعدة الثالثة لليد اليمنى لتحديد اتجاه القوة المؤثرة في السلك. (c) ما اتجاه القوة إذا عُكس التيار ليسري نحو الشرق؟', null, null, null, 'تطبيق', 'تحديد اتجاه القوة', 'متوسط', 'الكتاب ص 91 — مراجعة السؤال 25، وص 99 السؤال 78'),
('essay', 2, 'يبين الشكل الآتي حلقة سلكية مستطيلة في مستوى الورقة بين قطبي مغناطيس، والمجال المغناطيسي B يتجه من N (يسارًا) إلى S (يمينًا). يسري التيار في الضلع (1) إلى أعلى الصفحة، وفي الضلع (2) إلى أسفلها، وفي الضلعين العلوي والسفلي أفقيًّا. (a) حدّد اتجاه القوة المؤثرة في كل من الضلعين (1) و(2). (b) ما القوة المؤثرة في الضلعين العلوي والسفلي؟ ولماذا؟ (c) ماذا يحدث للحلقة نتيجة لذلك؟', null, '[{"src":"qimg/phys32/c3l2-o06-e2.svg","alt":"قطب مغناطيسي شمالي N على اليسار وقطب جنوبي S على اليمين، وبينهما أربعة خطوط مجال خضراء أفقية تتجه إلى اليمين ويرمز لها B. بين القطبين حلقة سلكية مستطيلة في مستوى الورقة. داخل الضلع الأيسر المسمّى «الضلع (1)» سهم تيار I إلى أعلى الصفحة، وداخل الضلع الأيمن المسمّى «الضلع (2)» سهم تيار I إلى أسفل الصفحة، وفوق الضلع العلوي سهم تيار إلى اليمين، وتحت الضلع السفلي سهم تيار إلى اليسار."}]'::jsonb, null, 'تحليل', 'تحديد اتجاه القوة', 'صعب', 'الكتاب ص 85 — الشكل 19-3 وتطبيق القاعدة الثالثة على جانبي الحلقة'),
('essay', 3, 'حدّد اتجاه القوة المغناطيسية في كل حالة من الحالات الثلاث المبينة في الشكل الآتي، موضحًا كيف وضعت يدك في كل حالة: (1) سلك يسري فيه تيار إلى اليسار في مجال خارج من الورقة. (2) سلك رأسي يسري فيه تيار إلى أسفل الصفحة في مجال يتجه إلى اليمين. (3) بروتون يتحرك إلى اليسار في مجال يتجه إلى أعلى الصفحة.', null, '[{"src":"qimg/phys32/c3l2-o06-e3.svg","alt":"ثلاث حالات متجاورة. (1) سلك أفقي في مجال B خارج من الورقة تمثله نقاط خضراء، وفوق السلك سهم التيار I يتجه إلى اليسار. (2) سلك رأسي تقطعه ثلاثة خطوط مجال خضراء أفقية تتجه إلى اليمين ويرمز لها B، وبجانب السلك سهم التيار I يتجه إلى أسفل الصفحة. (3) ثلاثة خطوط مجال خضراء رأسية تتجه إلى أعلى الصفحة ويرمز لها B، وبينها بروتون (دائرة وردية مكتوب تحتها «بروتون») يخرج منه سهم أحمر للسرعة v يتجه إلى اليسار."}]'::jsonb, null, 'تطبيق', 'تحديد اتجاه القوة', 'سهل', 'الكتاب ص 82 — القاعدة الثالثة لليد اليمنى والرمزان (×) و(•)، وص 89')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'بالقاعدة الثالثة لليد اليمنى: الأصابع إلى داخل الورقة (المجال)، والإبهام إلى اليمين (التيار)، فيكون باطن الكف متجهًا إلى أعلى الصفحة؛ فالقوة إلى أعلى الصفحة.', '["هذا عكس الاتجاه الصحيح؛ ويحدث عند استخدام اليد اليسرى أو عكس دوري الإبهام والأصابع.","القوة عمودية على المجال الداخل في الورقة، فلا تكون إلى داخلها.","","القوة عمودية على المجال، فلا تكون إلى خارج الورقة أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (68%)"}],"at":"2026-11-28T06:03:18.378Z"}'::jsonb),
('mcq', 2, 0, 'الأصابع خارجة من الورقة (المجال)، والإبهام إلى أعلى الصفحة (التيار)، فيتجه العمودي على باطن الكف إلى يمين الصفحة؛ فالقوة إلى اليمين.', '["","هذا عكس الاتجاه الصحيح؛ ويحدث عند عكس دوري الإبهام والأصابع.","القوة عمودية على المجال الخارج من الورقة، فلا تكون إلى داخلها.","القوة لا تكون في اتجاه المجال، بل عمودية عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-28T06:03:18.378Z"}'::jsonb),
('mcq', 3, 1, 'الأصابع إلى اليسار (المجال)، والإبهام خارج من الورقة (التيار)، فيتجه العمودي على باطن الكف إلى أسفل الصفحة؛ فالقوة إلى أسفل الصفحة.', '["هذا عكس الاتجاه الصحيح؛ وهو ما يحدث لو كان التيار داخلًا في الورقة.","","القوة عمودية على المجال، فلا تكون في اتجاهه.","القوة عمودية على المجال، فلا تكون عكس اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-28T06:03:18.378Z"}'::jsonb),
('mcq', 4, 0, 'المجال بين القطبين يتجه من N إلى S، أي إلى أسفل الصفحة. الأصابع إلى أسفل (المجال)، والإبهام إلى اليمين (التيار)، فيتجه العمودي على باطن الكف إلى داخل الورقة؛ فالقوة إلى داخل الورقة.', '["","القوة لا تتجه نحو أحد القطبين؛ فهي عمودية على المجال الرأسي.","هذا عكس الاتجاه الصحيح؛ ويحدث عند عدّ المجال متجهًا من S إلى N.","القوة لا تكون في اتجاه المجال (من N إلى S)، بل عمودية عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.379Z"}'::jsonb),
('mcq', 5, 2, 'البروتون موجب الشحنة، فتُطبق القاعدة الثالثة لليد اليمنى مباشرة: الأصابع إلى داخل الورقة (المجال)، والإبهام إلى أعلى الصفحة (السرعة)، فيتجه العمودي على باطن الكف إلى يسار الصفحة.', '["هذا اتجاه القوة لو كان الجسيم إلكترونًا سالب الشحنة.","القوة عمودية على المجال الداخل في الورقة، فلا تكون إلى خارجها.","","القوة عمودية على السرعة، فلا تكون عكس اتجاه الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-28T06:03:18.379Z"}'::jsonb),
('mcq', 6, 3, 'الأصابع إلى اليسار (المجال)، والإبهام إلى أسفل الصفحة (التيار)، فيتجه العمودي على باطن الكف إلى داخل الورقة؛ فالقوة إلى داخل الورقة.', '["هذا عكس الاتجاه الصحيح؛ وهو ما يحدث لو كان التيار إلى أعلى الصفحة.","القوة لا تكون في اتجاه المجال بل عمودية عليه.","القوة عمودية على المجال الأفقي، فلا تكون عكس اتجاهه إلى اليمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-28T06:03:18.379Z"}'::jsonb),
('mcq', 7, 2, 'المجال عمودي على السلك وعلى القوة معًا، فهو إما داخل في الورقة أو خارج منها. بالقاعدة الثالثة لليد اليمنى: الإبهام إلى أسفل الصفحة (التيار)، ولكي يتجه العمودي على باطن الكف إلى يسار الصفحة يجب أن تشير الأصابع إلى خارج الورقة؛ فالمجال خارج من الورقة.', '["المجال الداخل في الورقة يعطي قوة إلى يمين الصفحة، أي عكس القوة المعطاة.","المجال لا يكون في اتجاه القوة؛ فالقوة عمودية على المجال.","","المجال الموازي للتيار لا يؤثر بقوة في السلك؛ فالقوة تنعدم عندما يوازي السلك المجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-28T06:03:18.380Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) في المنظر العلوي يكون الشمال إلى أعلى الورقة والشرق إلى اليمين: سهم التيار إلى اليسار (الغرب)، وسهم المجال إلى أعلى الورقة (الشمال). (b) الأصابع نحو الشمال (المجال)، والإبهام نحو الغرب (التيار)، فيتجه العمودي على باطن الكف رأسيًّا إلى أسفل، أي نحو سطح الأرض. (c) عند عكس التيار نحو الشرق تنعكس القوة فتصبح رأسية إلى أعلى (بعيدًا عن سطح الأرض).', '["مخطط صحيح للتيار والمجال","تطبيق القاعدة بوضع الأصابع والإبهام","القوة رأسيًّا إلى أسفل","عند عكس التيار: القوة إلى أعلى"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"تطبيق القاعدة","marks":1},{"element":"اتجاه القوة في (b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"الاتجاه في (b) صحيح مع نقص في المخطط أو في (c)"},{"level":"1 درجة","description":"المخطط وحده صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ القوة نحو الشمال أو الجنوب (في مستوى المجال)","عكس دوري الإبهام والأصابع فتصبح القوة إلى أعلى في (b)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.380Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الضلع (1): الأصابع إلى اليمين (المجال) والإبهام إلى أعلى (التيار)، فالقوة إلى داخل الورقة. الضلع (2): الأصابع إلى اليمين والإبهام إلى أسفل، فالقوة إلى خارج الورقة. (b) لا تؤثر فيهما قوة؛ لأن التيار فيهما موازٍ للمجال أو معاكس له ($\theta = 0^\circ$ أو $180^\circ$) فيكون $\sin\theta = 0$. (c) تؤثر في الضلعين (1) و(2) قوتان متساويتان في المقدار ومتعاكستان في الاتجاه (إحداهما إلى داخل الورقة والأخرى إلى خارجها)، فتدور الحلقة حول محور رأسي يمر بمنتصفها.', '["قوة الضلع (1) إلى داخل الورقة","قوة الضلع (2) إلى خارج الورقة","لا قوة على الضلعين الموازيين للمجال مع التعليل","الحلقة تدور"]'::jsonb, '[]'::jsonb, '[{"element":"الضلع (1)","marks":1},{"element":"الضلع (2)","marks":1},{"element":"(b) مع التعليل","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"اتجاها القوتين صحيحان مع نقص في (b) أو (c)"},{"level":"1 درجة","description":"اتجاه قوة ضلع واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوتين على الضلعين في مستوى الورقة (إلى أعلى وأسفل)","القول إن الضلعين العلويين يتأثران بقوة","القول إن الحلقة تتحرك انتقاليًّا لا دورانيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.380Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) الأصابع خارجة من الورقة، والإبهام إلى اليسار، فالقوة إلى أعلى الصفحة. (2) الأصابع إلى اليمين، والإبهام إلى أسفل الصفحة، فالقوة إلى خارج الورقة. (3) البروتون موجب، فالأصابع إلى أعلى الصفحة، والإبهام إلى اليسار (اتجاه السرعة)، فالقوة إلى داخل الورقة.', '["(1) إلى أعلى الصفحة","(2) إلى خارج الورقة","(3) إلى داخل الورقة","وصف وضع اليد"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (1)","marks":1},{"element":"الحالة (2)","marks":1},{"element":"الحالة (3)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"حالتان صحيحتان"},{"level":"1 درجة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين رمز الخروج (•) والدخول (×)","عكس دوري الأصابع والإبهام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-28T06:03:18.381Z"}'::jsonb)
