('mcq', 1, 'أيّ مما يأتي يُعدّ تطبيقًا عمليًّا على القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي؟', null, null, '["المنصهر الكهربائي","مكبر الصوت","المصباح الكهربائي","البطارية الكهربائية"]'::jsonb, 'تذكر', 'تطبيق عملي', 'سهل', 'الكتاب ص 83 — مكبرات الصوت'),
('mcq', 2, 'ما تحول الطاقة الذي تقوم به سماعة مكبر الصوت؟', null, null, '["من طاقة كهربائية إلى طاقة صوتية","من طاقة صوتية إلى طاقة كهربائية","من طاقة كهربائية إلى طاقة حرارية","من طاقة حركية دورانية إلى طاقة كهربائية"]'::jsonb, 'تذكر', 'تطبيق عملي', 'سهل', 'الكتاب ص 83 — مكبرات الصوت (الشكل 18-3)'),
('mcq', 3, 'يبين الشكل الآتي مقطعًا تخطيطيًّا لمكبر صوت. ما الجزء المرقّم (2)؟', null, '[{"src":"qimg/phys32/c3l2-o07-spk.svg","alt":"مقطع تخطيطي لمكبر صوت (سماعة): مخروط على شكل شبه منحرف مكتوب عنده (1)، وعند قاعدته الضيقة ملف من سلك رفيع ملفوف مكتوب عنده (2)، وحول الملف وخلفه قطعة حمراء داكنة مكتوب عندها (3). يخرج سلكان من الخلف مكتوب عندهما «إلى المضخم»، وعلى يسار المخروط أقواس تمثل موجات صوتية."}]'::jsonb, '["مغناطيس دائم يولد المجال","مخروط ورقي يهتز فيحدث الصوت","ملف من سلك رفيع يسري فيه التيار","مضخم يرسل التيار الكهربائي"]'::jsonb, 'فهم', 'تحديد أجزاء جهاز', 'متوسط', 'الكتاب ص 83 — مكبرات الصوت (الشكل 18-3)'),
('mcq', 4, 'بين أيّ قيمتين يتغير عدد مرات تغير اتجاه التيار المار في ملف السماعة في الثانية، وفقًا لحدة الصوت الذي يمثله؟', null, null, '["بين 2 و2000 مرة في الثانية","بين 200 و200000 مرة في الثانية","بين 0 و20 مرة في الثانية","بين 20 و20000 مرة في الثانية"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 83 — مكبرات الصوت'),
('mcq', 5, 'لماذا يهتز المخروط الورقي في السماعة فيُحدث موجات صوتية؟', null, null, '["لأن اتجاه التيار في الملف يتغير، فيتغير اتجاه القوة المغناطيسية المؤثرة فيه، فيتحرك إلى الداخل والخارج","لأن المغناطيس الدائم يغير اتجاه مجاله باستمرار، فيجذب المخروط الورقي ثم يدفعه","لأن التيار يسخن الملف فيتمدد وينكمش بسرعة، فيدفع المخروط إلى الأمام والخلف","لأن المضخم يرسل موجات صوتية عبر السلكين إلى المخروط مباشرة فيهتز"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 83 — مكبرات الصوت'),
('mcq', 6, 'أيّ مجموعات الأجهزة الآتية تُعد جميعها تطبيقات على القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي؟', null, null, '["المنصهر الكهربائي، وقاطع الدائرة، والمقاومة المتغيرة","البطارية، والمصباح الكهربائي، والمدفأة الكهربائية","مكبر الصوت، والجلفانومتر، والمحرك الكهربائي","الأميتر الرقمي، والمقاومة الكهربائية، والمنصهر"]'::jsonb, 'تذكر', 'تطبيق عملي', 'متوسط', 'الكتاب ص 83 و85 و87، وص 95 المفاهيم الرئيسة'),
('mcq', 7, 'وُصلت سماعة ببطارية فسرى في ملفها تيار ثابت المقدار والاتجاه. ماذا تتوقع أن يحدث؟', null, null, '["يهتز المخروط باستمرار ويُصدر صوتًا ثابت الحدة","لا يتأثر الملف بأي قوة لأن التيار ثابت","يدور الملف والمخروط دورانًا مستمرًّا كالمحرك","يُدفع الملف مرة واحدة في اتجاه واحد ويبقى، فلا يُسمع صوت مستمر"]'::jsonb, 'تحليل', 'توقع نتيجة', 'صعب', 'الكتاب ص 83 — مكبرات الصوت'),
('essay', 1, 'اذكر ثلاثة تطبيقات عملية على القوة المغناطيسية المؤثرة في سلك (أو ملف) يسري فيه تيار موضوع في مجال مغناطيسي، وبيّن ما يحدث للملف في كل منها.', null, null, null, 'تذكر', 'تطبيق عملي', 'سهل', 'الكتاب ص 83 و85 و87، وص 95 المفاهيم الرئيسة'),
('essay', 2, 'يبين الشكل الآتي مقطعًا تخطيطيًّا لمكبر صوت. (a) سمّ الأجزاء المرقّمة (1) و(2) و(3). (b) وضّح كيف يحوّل مكبر الصوت التيار الكهربائي القادم من المضخم إلى صوت، مبيّنًا دور كل جزء. (c) ما الذي يحدد حدة الصوت الناتج؟', null, '[{"src":"qimg/phys32/c3l2-o07-spk.svg","alt":"مقطع تخطيطي لمكبر صوت (سماعة): مخروط على شكل شبه منحرف مكتوب عنده (1)، وعند قاعدته الضيقة ملف من سلك رفيع ملفوف مكتوب عنده (2)، وحول الملف وخلفه قطعة حمراء داكنة مكتوب عندها (3). يخرج سلكان من الخلف مكتوب عندهما «إلى المضخم»، وعلى يسار المخروط أقواس تمثل موجات صوتية."}]'::jsonb, null, 'فهم', 'شرح مبدأ عمل', 'صعب', 'الكتاب ص 83 — مكبرات الصوت (الشكل 18-3)، وص 95'),
('essay', 3, 'في سماعة مكبر صوت يتكوّن الملف من 200 لفة دائرية قطر كل منها 2.0 cm، ومقاومته 8.0 Ω، وفرق الجهد بين طرفيه 12 V، والمجال المغناطيسي المؤثر فيه 0.20 T وهو عمودي على سلك الملف في كل موضع. (a) ما مقدار التيار المار في الملف؟ (b) ما الطول الكلي لسلك الملف؟ (c) ما مقدار القوة المغناطيسية المؤثرة في الملف؟', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 101 — السؤال 91 (مكبر الصوت)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
