select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تُعد مكبرات الصوت إحدى التطبيقات العملية على القوة المغناطيسية المؤثرة في سلك يسري فيه تيار موضوع في مجال مغناطيسي؛ إذ يتأثر ملفها بقوة فيتحرك المخروط.', '["المنصهر يعمل بانصهار قطعة فلزية عند مرور تيار كبير، لا بالقوة المغناطيسية.","","المصباح يعمل بتسخين الفتيل بمرور التيار، لا بالقوة المغناطيسية.","البطارية مصدر للجهد تحوّل الطاقة الكيميائية إلى كهربائية، ولا تعتمد على هذه القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.381Z"}'::jsonb),
('mcq', 2, 0, 'تعمل السماعة على تحويل الطاقة الكهربائية إلى طاقة صوتية باستخدام ملف من سلك رفيع مثبت على مخروط ورقي موضوع في مجال مغناطيسي.', '["","هذا عكس عمل السماعة.","السماعة تحوّل الطاقة الكهربائية إلى صوت؛ والحرارة الناتجة فاقد غير مقصود.","هذا التحول لا يحدث في السماعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.381Z"}'::jsonb),
('mcq', 3, 2, 'الجزء (2) ملف من سلك رفيع مثبت على المخروط الورقي، يسري فيه التيار القادم من المضخم، وهو موضوع في المجال المغناطيسي للمغناطيس الدائم (3)، فيتأثر بقوة تحرّكه.', '["المغناطيس الدائم هو الجزء (3) المحيط بالملف.","المخروط الورقي هو الجزء (1).","","المضخم خارج السماعة ويتصل بها بالسلكين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.382Z"}'::jsonb),
('mcq', 4, 3, 'يرسل المضخم الذي يشغّل السماعة تيارًا كهربائيًّا خلال الملف، ويتغير اتجاه هذا التيار بين 20 و20000 مرة في الثانية، وذلك وفقًا لحدة الصوت الذي يمثله.', '["الحدان صغيران؛ فالمدى يمتد من 20 إلى 20000 مرة.","الحدان كبيران؛ فالمدى من 20 إلى 20000 مرة.","يتغير الاتجاه أكثر من ذلك بكثير، حتى 20000 مرة في الثانية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.382Z"}'::jsonb),
('mcq', 5, 0, 'يتأثر الملف الخفيف بقوة تدفعه نحو الداخل أو الخارج لأنه موجود في مجال مغناطيسي، وذلك اعتمادًا على اتجاه التيار المرسل من المضخم؛ فتغيّر اتجاه التيار يجعل الملف والمخروط المثبت عليه يهتزان محدثين موجات صوتية في الهواء.', '["","مجال المغناطيس الدائم ثابت؛ والذي يتغير هو اتجاه التيار في الملف.","الحركة سببها القوة المغناطيسية لا التمدد الحراري.","المضخم يرسل تيارًا كهربائيًّا لا موجات صوتية؛ والسماعة هي التي تحوّله إلى صوت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-28T06:03:18.382Z"}'::jsonb),
('mcq', 6, 2, 'في مكبر الصوت والجلفانومتر والمحرك الكهربائي يوجد ملف يسري فيه تيار موضوع في مجال مغناطيسي، فيتأثر بقوة مغناطيسية تحرّكه (اهتزازًا في السماعة، ودورانًا محدودًا في الجلفانومتر، ودورانًا مستمرًّا في المحرك).', '["هذه أدوات سلامة وتحكم في التيار، لا تعتمد على القوة المغناطيسية على سلك.","هذه الأجهزة تعتمد على الطاقة الكيميائية أو التأثير الحراري للتيار.","","هذه الأجهزة لا تعتمد على حركة ملف في مجال مغناطيسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-28T06:03:18.382Z"}'::jsonb),
('mcq', 7, 3, 'التيار الثابت في مجال مغناطيسي يُنتج قوة ثابتة المقدار والاتجاه، فيُدفع الملف والمخروط مرة واحدة إلى الداخل أو الخارج ثم يبقيان في وضعهما، ولا يحدث اهتزاز مستمر؛ لأن الاهتزاز يحتاج إلى تغيّر اتجاه التيار بين 20 و20000 مرة في الثانية.', '["الاهتزاز يتطلب تيارًا متغير الاتجاه، والتيار الثابت يُنتج قوة ثابتة.","التيار الثابت في مجال مغناطيسي يتأثر بقوة؛ لكنها ثابتة الاتجاه.","ملف السماعة مثبت على المخروط ولا يحوي عاكس تيار، فلا يدور دورانًا مستمرًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-28T06:03:18.382Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) مكبر الصوت (السماعة): يتأثر ملفه بقوة تدفعه إلى الداخل والخارج مع تغيّر اتجاه التيار فيهتز المخروط ويُحدث صوتًا، ويحوّل الطاقة الكهربائية إلى صوتية. (2) الجلفانومتر: يدور ملفه بمقدار يتناسب مع التيار فيُستخدم لقياس التيارات الصغيرة جدًّا. (3) المحرك الكهربائي: يدور ملفه دورانًا مستمرًّا، فيحوّل الطاقة الكهربائية إلى طاقة حركية دورانية.', '["مكبر الصوت مع ما يحدث لملفه","الجلفانومتر مع ما يحدث لملفه","المحرك الكهربائي مع ما يحدث لملفه"]'::jsonb, '[]'::jsonb, '[{"element":"التطبيق الأول","marks":1},{"element":"التطبيق الثاني","marks":1},{"element":"التطبيق الثالث","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"تطبيقان صحيحان مع ما يحدث فيهما"},{"level":"1 درجة","description":"تطبيق واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر المنصهر أو المصباح تطبيقًا على القوة المغناطيسية","ذكر التطبيق دون بيان ما يحدث للملف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-28T06:03:18.383Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) (1) مخروط ورقي، (2) ملف من سلك رفيع مثبت على المخروط، (3) مغناطيس دائم. (b) يرسل المضخم تيارًا كهربائيًّا خلال الملف، والملف موجود في المجال المغناطيسي للمغناطيس الدائم، فيتأثر بقوة مغناطيسية تدفعه إلى الداخل أو إلى الخارج وفق اتجاه التيار. ولأن اتجاه التيار يتغير باستمرار يهتز الملف، فيهتز المخروط المثبت عليه محدثًا موجات صوتية في الهواء. (c) عدد مرات تغير اتجاه التيار في الثانية (بين 20 و20000 مرة)، وفقًا لحدة الصوت الذي يمثله.', '["تسمية الأجزاء الثلاثة","قوة مغناطيسية على الملف في مجال المغناطيس","تغير اتجاه التيار يجعل الملف والمخروط يهتزان","الحدة تتحدد بعدد مرات تغير اتجاه التيار"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية الأجزاء","marks":1},{"element":"القوة على الملف","marks":1},{"element":"الاهتزاز وإحداث الصوت","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"التسمية والقوة صحيحتان مع نقص في تفسير الاهتزاز أو الحدة"},{"level":"1 درجة","description":"التسمية وحدها صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المغناطيس يتحرك ويهتز بدل الملف","القول إن المضخم يرسل صوتًا لا تيارًا","إغفال دور تغير اتجاه التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.383Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}} = \frac{12\ \text{V}}{8.0\ \Omega} = 1.5\ \text{A}$. (b) طول اللفة الواحدة يساوي محيطها $\pi d = \pi(0.020\ \text{m})$، وعدد اللفات $\mathrm{n} = 200$، فالطول الكلي $\mathrm{L} = \mathrm{n}\pi d = 200 \times \pi \times 0.020\ \text{m} = 12.6\ \text{m}$ (نحو 13 m). (c) $F = \mathrm{ILB} = (1.5\ \text{A})(12.6\ \text{m})(0.20\ \text{T}) = 3.8\ \text{N}$، وهي نفسها $\mathrm{nILB}$ حيث $\mathrm{L}$ طول اللفة الواحدة.', '["التيار 1.5 A","الطول الكلي = عدد اللفات × محيط اللفة ≈ 12.6 m","القوة ≈ 3.8 N"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}} = \\frac{12}{8.0} = 1.5\\ \\text{A}$","$\\mathrm{L} = \\mathrm{n}\\pi d = 200 \\times 3.14 \\times 0.020 = 12.6\\ \\text{m}$","$F = \\mathrm{ILB} = (1.5)(12.6)(0.20) = 3.77 \\approx 3.8\\ \\text{N}$"]'::jsonb, '[{"element":"التيار","marks":1},{"element":"طول السلك","marks":1},{"element":"القوة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"خطوتان صحيحتان"},{"level":"1 درجة","description":"حساب التيار فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال القطر بدل المحيط لطول اللفة","عدم تحويل 2.0 cm إلى 0.020 m","نسيان الضرب في عدد اللفات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.383Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
