from (values
('mcq', 1, 'ما المقصود بالجلفانومتر؟', null, null, '["جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا، ويمكن تحويله إلى أميتر أو فولتمتر","جهاز يحوّل الطاقة الكهربائية إلى طاقة حركية دورانية مستمرة باستخدام عاكس التيار","جهاز يستخدم لقياس فرق الجهد الكبير بين طرفي المصدر مباشرة دون أي تعديل","جهاز يولد مجالًا مغناطيسيًّا قويًّا عند مرور التيار فيه لرفع الأجسام الحديدية"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 85 — الجلفانومترات'),
('mcq', 2, 'ما المقصود بالمحرك الكهربائي؟', null, null, '["جهاز يستخدم لتحويل الطاقة الحركية الدورانية إلى طاقة كهربائية","جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا","جهاز يستخدم لتحويل الطاقة الكهربائية إلى طاقة حركية دورانية","جهاز يستخدم لتحويل الطاقة الكهربائية إلى طاقة صوتية"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 87 — المحرك الكهربائي'),
('mcq', 3, 'وفق تعريف الجلفانومتر، إلى أيّ الأجهزة يمكن تحويله؟', null, null, '["محرك كهربائي أو مولد","أميتر أو فولتمتر","مكبر صوت أو سماعة","منصهر أو قاطع دائرة"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 85 — الجلفانومترات'),
('mcq', 4, 'ماذا يُسمّى ملف المحرك الكهربائي المكوّن من لفات عديدة مثبتة على محور دوران؟', null, null, '["الملف اللولبي البسيط","عاكس التيار الكهربائي","مجزئ التيار الكهربائي","الملف ذو القلب الحديدي"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'متوسط', 'الكتاب ص 87 — المحرك الكهربائي'),
('mcq', 5, 'لماذا يصلح الجلفانومتر لقياس شدة التيار الكهربائي؟', null, null, '["لأن مقدار دوران ملفه يتناسب طرديًّا مع مقدار التيار المار فيه","لأن ملفه يدور دورة كاملة $360^\\circ$ عند مرور أي تيار فيه","لأن مغناطيسه يضعف بزيادة التيار فيتحرك المؤشر بمقدار الضعف","لأن نابضه يدور في اتجاه العزم الناتج عن التيار فيضاعف الدوران"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 85 — الجلفانومترات'),
('mcq', 6, 'ما اسم الجهاز المبين في الشكل الآتي، وما الغرض منه؟', null, '[{"src":"qimg/phys32/c3l2-o08-galv.svg","alt":"جهاز فيه مغناطيس على شكل حرف U قطبه الشمالي N على اليسار والجنوبي S على اليمين، ولكل قطب سطح مقعّر. بين القطبين أسطوانة رمادية حولها ملف (مكتوب عنده «ملف») يمكنه الدوران حول محور في المركز، ونابض حلزوني صغير عند المحور (مكتوب عنده «نابض»). يتصل بالملف مؤشر أحمر يتحرك أمام تدريج مقوّس في أعلى الجهاز. يدخل سلكان من أسفل الجهاز، وتحتهما سهمان للتيار I."}]'::jsonb, '["المحرك الكهربائي، ويحوّل الطاقة الكهربائية إلى حركية دورانية","الجلفانومتر، ويستخدم لقياس التيارات الكهربائية الصغيرة جدًّا","مكبر الصوت، ويحوّل الطاقة الكهربائية إلى طاقة صوتية","المغناطيس الكهربائي، ويستخدم لرفع قطع الحديد"]'::jsonb, 'فهم', 'تعرّف جهاز', 'متوسط', 'الكتاب ص 85 — الجلفانومترات (الشكل 19-3)'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة فيما يتعلق بالجلفانومتر والمحرك الكهربائي؟', null, null, '["الجلفانومتر يحوّل الطاقة الكهربائية إلى طاقة حركية دورانية مستمرة، والمحرك يقيس التيارات الصغيرة جدًّا","لا يحتوي أيّ منهما على مغناطيس؛ فكلاهما يعمل بمرور التيار الكهربائي في ملفه وحده","كلاهما يحتوي ملفًّا يسري فيه تيار في مجال مغناطيسي، لكن الجلفانومتر جهاز قياس والمحرك جهاز لتحويل الطاقة","المحرك جهاز قياس للتيارات الكبيرة، والجلفانومتر جهاز لتحويل الطاقة الكهربائية إلى صوتية"]'::jsonb, 'فهم', 'مقارنة تعريفات', 'صعب', 'الكتاب ص 85 و87، وص 95 المفردات'),
('essay', 1, 'عرّف كلًّا من: (a) الجلفانومتر. (b) المحرك الكهربائي. (c) الملف ذو القلب الحديدي.', null, null, null, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 85 و87، وص 95 المفردات'),
('essay', 2, 'يبين الشكل الآتي أحد أجهزة القياس. (a) ما اسم الجهاز؟ وعرّفه. (b) وضّح لماذا يمكن استخدام انحراف مؤشره لقياس التيار، مبيّنًا دور النابض. (c) إلى أيّ جهازين يمكن تحويله؟', null, '[{"src":"qimg/phys32/c3l2-o08-galv.svg","alt":"جهاز فيه مغناطيس على شكل حرف U قطبه الشمالي N على اليسار والجنوبي S على اليمين، ولكل قطب سطح مقعّر. بين القطبين أسطوانة رمادية حولها ملف (مكتوب عنده «ملف») يمكنه الدوران حول محور في المركز، ونابض حلزوني صغير عند المحور (مكتوب عنده «نابض»). يتصل بالملف مؤشر أحمر يتحرك أمام تدريج مقوّس في أعلى الجهاز. يدخل سلكان من أسفل الجهاز، وتحتهما سهمان للتيار I."}]'::jsonb, null, 'فهم', 'تعرّف جهاز وتعريفه', 'صعب', 'الكتاب ص 85 — الجلفانومترات (الشكل 19-3)'),
('essay', 3, 'يبين الشكل الآتي نموذجًا مبسطًا لجهاز كهربائي. (a) ما اسم الجهاز؟ وعرّفه. (b) ما صورة الطاقة الداخلة إليه، وما صورة الطاقة الناتجة؟ (c) يتكوّن الجهاز في الواقع من لفات عديدة لا من حلقة واحدة؛ فماذا تسمى هذه اللفات؟ وكيف يُنتج المجال المغناطيسي فيه؟ (d) بمَ يختلف هذا الجهاز في تعريفه عن الجلفانومتر؟', null, '[{"src":"qimg/phys32/c3l2-o08-motor.svg","alt":"قطب مغناطيسي شمالي N على اليسار وقطب جنوبي S على اليمين، وبينهما خطوط مجال خضراء أفقية إلى اليمين. بين القطبين حلقة سلكية مستطيلة، يتصل طرفاها من الأسفل بحلقة دائرية مقسومة إلى نصفين (مكتوب عندها «حلقة دائرية مقسومة»)، تلامسها فرشاتان على جانبيها (مكتوب عند إحداهما «فرشاة»)، والفرشاتان موصولتان ببطارية في أسفل الشكل."}]'::jsonb, null, 'فهم', 'تعرّف جهاز وتعريفه', 'صعب', 'الكتاب ص 87 — المحرك الكهربائي (الشكل 21-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
