('mcq', 1, 0, 'الجلفانومتر جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا، ويمكن تحويله إلى أميتر أو فولتمتر.', '["","هذا تعريف المحرك الكهربائي.","الجلفانومتر يقيس التيارات الصغيرة جدًّا، ولا يقيس فرق جهد كبيرًا إلا بعد تحويله إلى فولتمتر.","هذا وصف للمغناطيس الكهربائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-28T06:03:18.384Z"}'::jsonb),
('mcq', 2, 2, 'المحرك الكهربائي جهاز يستخدم لتحويل الطاقة الكهربائية إلى طاقة حركية دورانية.', '["هذا عكس عمل المحرك.","هذا تعريف الجلفانومتر.","","هذا عمل مكبر الصوت (السماعة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-28T06:03:18.384Z"}'::jsonb),
('mcq', 3, 1, 'الجلفانومتر جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا، ويمكن تحويله إلى أميتر أو فولتمتر.', '["الجلفانومتر جهاز قياس، ولا يُحوَّل إلى محرك أو مولد.","","السماعة لا تُصنع من الجلفانومتر بتحويله، والجلفانومتر جهاز قياس.","المنصهر وقاطع الدائرة أدوات سلامة لا أجهزة قياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.384Z"}'::jsonb),
('mcq', 4, 3, 'يتكوّن المحرك الكهربائي من لفات عديدة تثبت على محور دوران، وتسمى الملف ذا القلب الحديدي.', '["الملف اللولبي سلك ملفوف على شكل حلزون يولد مجالًا عند مرور التيار فيه، وليس اسم ملف المحرك.","عاكس التيار حلقة مقسومة إلى نصفين تعكس التيار، لا اللفات نفسها.","مجزئ التيار مقاومة صغيرة توصل مع الجلفانومتر على التوازي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.384Z"}'::jsonb),
('mcq', 5, 0, 'العزم المؤثر في ملف الجلفانومتر يتناسب طرديًّا مع مقدار التيار، والنابض يؤثر بعزم معاكس، فيتناسب مقدار الدوران طرديًّا مع التيار؛ لذا يُدرّج الجلفانومتر بمعرفة مقدار الدوران عند تيار معلوم ثم يُستخدم لقياس تيارات صغيرة غير معلومة.', '["","ملف الجلفانومتر يدور دورانًا محدودًا يتناسب مع التيار، لا دورة كاملة.","مجال المغناطيس الدائم لا يضعف بزيادة التيار.","النابض يؤثر بعزم معاكس لعزم التيار، لا في اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.384Z"}'::jsonb),
('mcq', 6, 1, 'الشكل يبين ملفًّا بين قطبي مغناطيس دائم يتصل بمؤشر يتحرك أمام تدريج ونابض يعيده؛ وهذا هو الجلفانومتر، وهو جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا.', '["المحرك لا يحوي مؤشرًا وتدريجًا ونابضًا، بل عاكس تيار وفرشاتين.","","مكبر الصوت يحوي مخروطًا ورقيًّا، لا مؤشرًا وتدريجًا.","المغناطيس الكهربائي لا يحوي مغناطيسًا دائمًا ومؤشرًا وتدريجًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.385Z"}'::jsonb),
('mcq', 7, 2, 'في كلا الجهازين ملف يسري فيه تيار موضوع في مجال مغناطيسي فيتأثر بقوة؛ لكن الجلفانومتر يُعرَّف بأنه جهاز لقياس التيارات الصغيرة جدًّا، والمحرك بأنه جهاز لتحويل الطاقة الكهربائية إلى طاقة حركية دورانية.', '["هذا تبديل لتعريفي الجهازين.","كلاهما يحتاج إلى مجال مغناطيسي يؤثر في الملف؛ فلا حركة دونه.","","المحرك ليس جهاز قياس، والجلفانومتر لا يحوّل الطاقة إلى صوت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.385Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الجلفانومتر: جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا، ويمكن تحويله إلى أميتر أو فولتمتر. (b) المحرك الكهربائي: جهاز يستخدم لتحويل الطاقة الكهربائية إلى طاقة حركية دورانية. (c) الملف ذو القلب الحديدي: لفات عديدة من السلك تثبت على محور دوران في المحرك الكهربائي.', '["تعريف الجلفانومتر","تعريف المحرك الكهربائي","تعريف الملف ذي القلب الحديدي"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2 درجتان","description":"تعريفان صحيحان"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المحرك بأنه يحوّل الطاقة الحركية إلى كهربائية","تعريف الجلفانومتر بأنه يقيس التيارات الكبيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.385Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الجلفانومتر، وهو جهاز يستخدم لقياس التيارات الكهربائية الصغيرة جدًّا. (b) عند مرور تيار في الملف الموضوع في مجال المغناطيس يتأثر جانبا الملف بقوتين متعاكستين فيتولد عزم يدير الملف، وهذا العزم يتناسب طرديًّا مع التيار. ويؤثر النابض بعزم معاكس، فيستقر الملف عند دوران يتناسب طرديًّا مع التيار؛ لذا يُدرّج الجهاز بتيار معلوم ثم يقيس تيارات صغيرة غير معلومة. (c) يمكن تحويله إلى أميتر أو فولتمتر.', '["الاسم والتعريف","عزم على الملف يتناسب مع التيار","النابض يؤثر بعزم معاكس فيتناسب الدوران مع التيار","التحويل إلى أميتر أو فولتمتر"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"العزم والتيار","marks":1},{"element":"دور النابض","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"الاسم والتعريف صحيحان مع نقص في التفسير"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الجهاز محركًا","القول إن النابض يزيد دوران الملف","القول إن ملف الجلفانومتر يدور دورة كاملة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.385Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المحرك الكهربائي، وهو جهاز يستخدم لتحويل الطاقة الكهربائية إلى طاقة حركية دورانية. (b) الطاقة الداخلة كهربائية (من البطارية)، والناتجة طاقة حركية دورانية. (c) تسمى الملف ذا القلب الحديدي، ويُنتج المجال المغناطيسي بمغناطيس دائم أو بمغناطيس كهربائي. (d) الجلفانومتر جهاز قياس للتيارات الصغيرة جدًّا يدور ملفه دورانًا محدودًا، أما المحرك فجهاز لتحويل الطاقة يدور ملفه دورانًا مستمرًّا.', '["الاسم والتعريف","صورتا الطاقة","الملف ذو القلب الحديدي ومصدر المجال","الفرق عن الجلفانومتر"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابة كاملة وصحيحة مع التعليل أو الخطوات"},{"level":"2–3 درجات","description":"الاسم والتعريف صحيحان مع نقص في جزأين"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الجهاز مولدًا","عكس صورتي الطاقة","تسمية اللفات الملف اللولبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.385Z"}'::jsonb)
