from (values
('mcq', 1, 'أيّ المخططات الأربعة الآتية يحوّل الجلفانومتر إلى أميتر يقيس تيارات أكبر؟', null, '[{"src":"qimg/phys32/c3l2-o09-four.svg","alt":"أربعة مخططات مرقّمة لجلفانومتر G مع مقاومة: (1) الجلفانومتر ومقاومة 0.05 Ω موصولان على التوالي. (2) الجلفانومتر ومقاومة 50 kΩ موصولان على التوازي. (3) الجلفانومتر ومقاومة 0.05 Ω موصولان على التوازي. (4) الجلفانومتر ومقاومة 50 kΩ موصولان على التوالي."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (3)","المخطط (4)"]'::jsonb, 'فهم', 'مفاهيمي', 'سهل', 'الكتاب ص 86 — الأميتر'),
('mcq', 2, 'ماذا تُسمّى المقاومة الصغيرة جدًّا الموصولة على التوازي مع الجلفانومتر لتحويله إلى أميتر؟', null, null, '["مجزئ التيار","المضاعف","عاكس التيار","الفرشاة"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 86 — الأميتر، وص 99 السؤال 68'),
('mcq', 3, 'في المخطط الآتي لجلفانومتر حُوِّل إلى أميتر، ما العلاقة بين التيارين $\mathrm{I}_\mathrm{m}$ و$\mathrm{I}_\mathrm{s}$؟', null, '[{"src":"qimg/phys32/c3l2-o09-ammeter.svg","alt":"مخطط جلفانومتر (دائرة فيها الحرف G) في السلك العلوي، وتحته مقاومة R مجزئ موصولة معه على التوازي بين نقطتي تفرّع، ولكل منهما طرف توصيل في الأسفل: الأيسر موجب (+) والأيمن سالب (−). سهم التيار في فرع الجلفانومتر مكتوب عنده I_m، وسهم التيار في فرع المقاومة مكتوب عنده I_s، والسهمان نحو اليمين."}]'::jsonb, '["$\\mathrm{I}_\\mathrm{m}$ أكبر كثيرًا من $\\mathrm{I}_\\mathrm{s}$","$\\mathrm{I}_\\mathrm{m}$ يساوي $\\mathrm{I}_\\mathrm{s}$ دائمًا","$\\mathrm{I}_\\mathrm{s}$ يساوي صفرًا دائمًا","$\\mathrm{I}_\\mathrm{s}$ أكبر كثيرًا من $\\mathrm{I}_\\mathrm{m}$"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 86 — الأميتر'),
('mcq', 4, 'لماذا يجب أن تكون المقاومة الكلية للأميتر صغيرة جدًّا؟', null, null, '["حتى يمر التيار كله في ملف الجلفانومتر فيزداد انحرافه","حتى لا يؤثر الأميتر في مقدار التيار الذي يقيسه في الدائرة","حتى يسحب الأميتر تيارًا صغيرًا جدًّا من الدائرة التي يقيسها","حتى يمكن توصيل الأميتر على التوازي مع العنصر المراد قياس تياره"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 86 — الأميتر'),
('mcq', 5, 'كيف يوصل الأميتر الناتج عن تحويل الجلفانومتر في الدائرة الكهربائية لقياس التيار المار في مصباح؟', null, null, '["على التوالي مع المصباح","على التوازي مع المصباح","على التوازي مع البطارية","بين طرفي المصباح بعد فصله"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 86 — الأميتر، الشكل 20c'),
('mcq', 6, 'حُوِّل جلفانومتر إلى أميتر، ثم استُبدل مجزئ التيار بمقاومة أصغر منه. ماذا يحدث لأقصى تيار يمكن أن يقيسه الأميتر؟', null, null, '["يقل، لأن مقاومة الأميتر الكلية أصبحت أصغر","لا يتغير، لأن الجلفانومتر نفسه لم يتغير","يزداد، لأن جزءًا أكبر من التيار يمر في المجزئ","يزداد، لأن تيارًا أكبر يمر في ملف الجلفانومتر"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 86 — الأميتر'),
('mcq', 7, 'ينحرف مؤشر جلفانومتر حساس إلى أقصى تدريج عند تيار صغير مثل 50 μA. ما سبب توصيل مقاومة صغيرة جدًّا معه على التوازي عند استعماله لقياس تيار مقداره 2 A؟', null, null, '["لزيادة التيار المار في ملف الجلفانومتر","لزيادة المقاومة الكلية للجهاز لحماية الدائرة","لعكس اتجاه التيار في الملف كل نصف دورة","ليمر معظم التيار في المقاومة فلا يتجاوز تيار الملف حدّه"]'::jsonb, 'تطبيق', 'مفاهيمي', 'صعب', 'الكتاب ص 86 — الأميتر'),
('essay', 1, 'اعتمادًا على المخطط الآتي، وضّح كيف يُحوَّل الجلفانومتر إلى أميتر، مبيّنًا: نوع المقاومة المضافة وطريقة توصيلها واسمها، وكيف ينقسم التيار بين فرعي المخطط، وطريقة توصيل الأميتر الناتج في الدائرة ولماذا.', null, '[{"src":"qimg/phys32/c3l2-o09-ammeter.svg","alt":"مخطط جلفانومتر (دائرة فيها الحرف G) في السلك العلوي، وتحته مقاومة R مجزئ موصولة معه على التوازي بين نقطتي تفرّع، ولكل منهما طرف توصيل في الأسفل: الأيسر موجب (+) والأيمن سالب (−). سهم التيار في فرع الجلفانومتر مكتوب عنده I_m، وسهم التيار في فرع المقاومة مكتوب عنده I_s، والسهمان نحو اليمين."}]'::jsonb, null, 'فهم', 'مقالي', 'متوسط', 'الكتاب ص 86 — الأميتر، والشكل 20a، وص 95'),
('essay', 2, 'وصل طالب أميترًا (جلفانومترًا مع مجزئ تيار) على التوازي مع مصباح متصل ببطارية بدلًا من توصيله على التوالي. فسّر ما يحدث، وبيّن الخطأ في طريقة التوصيل.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 86 — الأميتر، الشكل 20c'),
('essay', 3, 'لديك جلفانومتر ينحرف مؤشره إلى أقصى تدريج عند تيار صغير. فسّر لماذا لا يصلح وحده لقياس تيار مصباح سيارة مثلًا، وكيف يمكن جعله يقيس هذا التيار، ولماذا يجب إعادة معايرة تدريجه بعد ذلك.', null, null, null, 'فهم', 'مقالي', 'متوسط', 'الكتاب ص 85–86 — الجلفانومترات والأميتر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
