from (values
('mcq', 1, 2, 'يُحوَّل الجلفانومتر إلى أميتر بتوصيل مقاومة صغيرة جدًّا على التوازي معه، فيمر معظم التيار فيها، وهذا ما يبيّنه المخطط (3) (مقاومة 0.05 Ω على التوازي).', '["المقاومة الصغيرة على التوالي لا تُمرّر أي جزء من التيار بعيدًا عن الملف، فيمر التيار كله في الجلفانومتر.","المقاومة الكبيرة على التوازي لا تأخذ إلا جزءًا ضئيلًا من التيار، فلا تحمي الجلفانومتر ولا توسّع مداه عمليًّا.","","المقاومة الكبيرة على التوالي تحوّل الجلفانومتر إلى فولتمتر لا إلى أميتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.386Z"}'::jsonb),
('mcq', 2, 0, 'المقاومة الصغيرة جدًّا الموصولة على التوازي مع الجلفانومتر يمر فيها معظم التيار فتُسمّى مجزئ التيار.', '["","المضاعف مقاومة كبيرة توصل على التوالي لتحويل الجلفانومتر إلى فولتمتر.","عاكس التيار حلقة مقسومة في المحرك الكهربائي تعكس اتجاه التيار في الملف.","الفرشاة نقطة تلامس من الجرافيت توصل التيار إلى عاكس التيار في المحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.386Z"}'::jsonb),
('mcq', 3, 3, 'الفرعان على التوازي فرق الجهد بين طرفيهما واحد، والتيار يتناسب عكسيًّا مع المقاومة؛ ولأن مقاومة مجزئ التيار صغيرة جدًّا يمر فيها معظم التيار $\mathrm{I}_\mathrm{s}$، ولا يمر في الجلفانومتر إلا تيار صغير $\mathrm{I}_\mathrm{m}$ (بضعة ميكروأمبيرات).', '["عكس العلاقة: الجلفانومتر مقاومته كبيرة نسبيًّا فلا يمر فيه إلا تيار صغير.","الفرعان مقاومتاهما مختلفتان جدًّا، فلا ينقسم التيار بينهما بالتساوي.","المقاومة الصغيرة الموصولة على التوازي يمر فيها معظم التيار لا تيار صفري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-28T06:03:18.386Z"}'::jsonb),
('mcq', 4, 1, 'يوصل الأميتر في الدائرة على التوالي فيمر فيه تيار الدائرة كله، ولذلك تُجعل مقاومته الكلية صغيرة جدًّا حتى لا تُغيّر مقاومة الدائرة ولا تؤثر في مرور التيار المراد قياسه.', '["المقصود عكس ذلك: معظم التيار يمر في مجزئ التيار لا في الملف، فلا يتلف الجلفانومتر.","","سحب تيار صغير صفة الفولتمتر ذي المقاومة الكبيرة؛ أما الأميتر فيمر فيه تيار الدائرة كله.","الأميتر يوصل على التوالي لا على التوازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.386Z"}'::jsonb),
('mcq', 5, 0, 'يجب أن يمر في الأميتر التيار نفسه المار في المصباح، لذلك يوصل معه على التوالي، ومقاومته الصغيرة جدًّا لا تؤثر في التيار.', '["","التوصيل على التوازي طريقة توصيل الفولتمتر لقياس فرق الجهد.","توصيله على التوازي مع البطارية يجعله يقيس تيارًا لا يمر في المصباح، وقد يتلف لصغر مقاومته.","فصل المصباح يقطع الدائرة فلا يمر فيه تيار ليُقاس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.386Z"}'::jsonb),
('mcq', 6, 2, 'أقصى انحراف يحدث عند تيار ثابت صغير في الملف. عندما تصغر مقاومة المجزئ يمر فيه جزء أكبر من التيار الكلي، فيلزم تيار كلي أكبر ليصل تيار الملف إلى قيمته القصوى؛ أي يزداد أقصى تدريج للأميتر. ولهذا يُختار مجزئ التيار وفق تدريج الانحراف المطلوب.', '["صغر المقاومة الكلية يعني أن الأميتر يُمرّر تيارًا كليًّا أكبر قبل أن يصل الملف إلى أقصى انحرافه، لا أصغر.","الملف واحد، لكن نسبة انقسام التيار بين الملف والمجزئ تغيّرت فتغيّر المدى.","","أقصى تيار في الملف ثابت لا يتغير؛ الزيادة كلها تمر في المجزئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.387Z"}'::jsonb),
('mcq', 7, 3, 'تيار 2 A أكبر كثيرًا من 50 μA الذي يُحدث أقصى انحراف، فيوصل مجزئ تيار صغير على التوازي يمر فيه معظم التيار، ويبقى تيار الملف صغيرًا ضمن تدريجه.', '["الهدف إنقاص تيار الملف لا زيادته؛ فتيار 2 A يتلف الملف أو يتجاوز تدريجه.","توصيل مقاومة على التوازي يُصغّر المقاومة الكلية ولا يكبّرها.","عكس التيار كل نصف دورة وظيفة عاكس التيار في المحرك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.387Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يوصل بالجلفانومتر مقاومة صغيرة جدًّا على التوازي تسمى مجزئ التيار $R_{\text{مجزئ}}$. ولأن الفرعين على التوازي والتيار يتناسب عكسيًّا مع المقاومة يمر معظم التيار $\mathrm{I}_\mathrm{s}$ في المجزئ، ويمر في ملف الجلفانومتر تيار صغير $\mathrm{I}_\mathrm{m}$ (بضعة ميكروأمبيرات) يتناسب مع التيار الكلي فيُقرأ على التدريج. وتصبح المقاومة الكلية للأميتر صغيرة جدًّا، فيوصل في الدائرة على التوالي دون أن يؤثر في مرور التيار.', '["مقاومة صغيرة جدًّا على التوازي","اسمها مجزئ التيار","معظم التيار يمر في المجزئ وجزء صغير في الملف","يوصل الأميتر على التوالي ومقاومته الكلية صغيرة فلا يؤثر في التيار"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المقاومة وطريقة توصيلها","marks":1},{"element":"اسم المقاومة","marks":1},{"element":"انقسام التيار","marks":1},{"element":"توصيل الأميتر في الدائرة وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين مجزئ التيار والمضاعف","القول إن معظم التيار يمر في الجلفانومتر","توصيل الأميتر على التوازي مع العنصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.387Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مقاومة الأميتر الكلية صغيرة جدًّا، فإذا وُصل على التوازي مع المصباح مرّ فيه معظم تيار الدائرة بدل أن يمر في المصباح، فيكاد المصباح ينطفئ، ويمر في الأميتر تيار كبير قد يتجاوز أقصى تدريجه ويتلفه، ولا تمثّل قراءته تيار المصباح. والصواب توصيله على التوالي مع المصباح ليمر فيه التيار نفسه.', '["مقاومة الأميتر صغيرة جدًّا","يمر معظم التيار في الأميتر بدل المصباح فيخفت المصباح","تيار كبير قد يتلف الأميتر وقراءته لا تمثّل تيار المصباح","الصواب التوصيل على التوالي"]'::jsonb, '[]'::jsonb, '[{"element":"مقاومة الأميتر الصغيرة","marks":1},{"element":"أثر ذلك في المصباح","marks":1},{"element":"أثره في الأميتر وقراءته","marks":1},{"element":"التوصيل الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن الأميتر يقيس تيار المصباح وهو موصول على التوازي","نسيان أن مقاومة الأميتر صغيرة جدًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.387Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجلفانومتر يقيس التيارات الصغيرة جدًّا فقط (ينحرف إلى أقصى تدريج عند نحو 50 μA)، وتيار المصباح أكبر كثيرًا فيتجاوز تدريجه وقد يتلف ملفه. لجعله يقيسه يوصل معه على التوازي مجزئ تيار صغير جدًّا فيمر فيه معظم التيار ويبقى تيار الملف صغيرًا. وبما أن تيار الملف أصبح جزءًا ثابت النسبة من التيار الكلي، يُدرَّج المؤشر من جديد بقيم التيار الكلي (بالأمبير) لا بتيار الملف.', '["الجلفانومتر يقيس تيارات صغيرة جدًّا فقط","توصيل مجزئ تيار صغير على التوازي","تيار الملف نسبة ثابتة من التيار الكلي فيُعاد تدريجه بالتيار الكلي"]'::jsonb, '[]'::jsonb, '[{"element":"حدود الجلفانومتر","marks":1},{"element":"إضافة مجزئ التيار على التوازي","marks":1},{"element":"سبب إعادة المعايرة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول بإضافة مقاومة كبيرة على التوالي","إغفال إعادة تدريج المؤشر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-28T06:03:18.387Z"}'::jsonb)
