('mcq', 6, 'حُوِّل جلفانومتر إلى فولتمتر بمضاعف معيّن، ثم استُبدل المضاعف بمقاومة أكبر. كيف يتغيّر أقصى تدريج للفولتمتر؟', null, null, '["يقل، لأن التيار المار في الملف يقل","لا يتغير، لأن أقصى تيار للملف ثابت","يقل، لأن المقاومة الكلية تزداد","يزداد، لأن جهدًا أكبر يلزم لإمرار التيار نفسه"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 97 — السؤال 54، وص 86'),
('mcq', 7, 'يُراد جعل مؤشر فولتمتر ينحرف إلى أقصى تدريج عند فرق جهد 10 V. ما الذي يجب أن يتحقق عند اختيار المضاعف؟', null, null, '["أن تساوي مقاومة المضاعف مقاومة ملف الجلفانومتر","أن يكون التيار المار في المضاعف 10 A","أن يمر في الملف تيار الانحراف الأقصى عند 10 V","أن يكون فرق الجهد بين طرفي الملف 10 V"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 86 — الفولتميتر'),
('essay', 1, 'اعتمادًا على المخطط الآتي، وضّح كيف يُحوَّل الجلفانومتر إلى فولتمتر، مبيّنًا: المقاومة المضافة وطريقة توصيلها واسمها، والكمية التي يستجيب لها الملف وعلاقتها بفرق الجهد، وطريقة توصيل الفولتمتر في الدائرة ولماذا.', null, '[{"src":"qimg/phys32/c3l2-o10-voltmeter.svg","alt":"مخطط جلفانومتر (دائرة فيها الحرف G) في السلك العلوي، موصول على التوالي بمقاومة R مضاعف في السلك الرأسي الأيسر، وللدائرة طرفا توصيل في الأسفل: الأيسر موجب (+) والأيمن سالب (−). سهم صغير بجانب المقاومة مكتوب عنده I يبين اتجاه التيار إلى أعلى."}]'::jsonb, null, 'فهم', 'مقالي', 'متوسط', 'الكتاب ص 86 — الفولتميتر، والشكل 20b، وص 95'),
('essay', 2, 'استعمل طالب جلفانومترًا موصولًا بمقاومة صغيرة على التوالي على أنه فولتمتر، ووصله بين طرفي مصباح في دائرة. فسّر لماذا تكون قراءته غير صحيحة وقد يتلف، واقترح التعديل اللازم.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 86 — الفولتميتر'),
('essay', 3, 'فولتمتران مصنوعان من جلفانومترين متماثلين، مقاومة الأول الكلية أكبر من مقاومة الثاني. بيّن، مستعينًا بالعلاقة $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}}$، أيهما أقصى تدريج له أكبر، وأيهما أقل تأثيرًا في الدائرة عند توصيله، مع التعليل.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 97 — السؤال 54، وص 86')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
