insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يُحوَّل الجلفانومتر إلى فولتمتر بتوصيله بمقاومة كبيرة على التوالي تسمى مجزئ الجهد (المضاعف)، فتصبح مقاومته الكلية كبيرة جدًّا.', '["هذه طريقة تحويله إلى أميتر (مجزئ التيار).","","المقاومة الصغيرة على التوالي لا ترفع المقاومة الكلية، فيسحب الجهاز تيارًا كبيرًا ويتجاوز تدريجه عند جهد صغير.","المقاومة على التوازي لا تحدّ التيار المار في الملف، فيبقى الجهاز كأنه جلفانومتر منخفض المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.388Z"}'::jsonb),
('mcq', 2, 0, 'المقاومة موصولة مع الجلفانومتر على التوالي، وهذه طريقة تحويله إلى فولتمتر؛ وتُسمّى هذه المقاومة المضاعف.', '["","الأميتر يتطلب مقاومة صغيرة على التوازي مع الجلفانومتر، والمقاومة هنا على التوالي.","المحرك جهاز لتحويل الطاقة الكهربائية إلى حركية دورانية ولا يتكوّن من جلفانومتر ومقاومة.","مكبر الصوت ملف مثبت على مخروط في مجال مغناطيسي وليس جهاز قياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.388Z"}'::jsonb),
('mcq', 3, 3, 'يقيس الجلفانومتر التيار المار في المقاومة الكبيرة المضافة، ويُحسب التيار بالعلاقة $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}}$؛ ولأن المقاومة الكلية ثابتة يتناسب التيار طرديًّا مع فرق الجهد، فيُدرَّج المؤشر بالفولت.', '["الجلفانومتر يستجيب للتيار المار فيه، ويُدرَّج الجهاز بفرق الجهد بين طرفي المجموعة كلها لا الملف وحده.","المقاومة الكلية ثابتة يُختار مقدارها مسبقًا، ولا يقيسها الجهاز.","المقاومة لا تختزن شحنة؛ الجلفانومتر يستجيب للتيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.388Z"}'::jsonb),
('mcq', 4, 2, 'يوصل الفولتمتر على التوازي مع العنصر، ومقاومته الكلية الكبيرة جدًّا تجعله يسحب تيارًا ضئيلًا، فلا يؤثر في مرور التيار في الدائرة ولا في فرق الجهد الذي يقيسه.', '["هذا عكس المطلوب؛ مرور تيار كبير فيه يغيّر تيارات الدائرة وجهودها.","الفولتمتر يوصل على التوازي مع العنصر لا على التوالي.","","المقاومة الكبيرة تجعل أقصى انحراف عند جهد أكبر لا أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-28T06:03:18.388Z"}'::jsonb),
('mcq', 5, 0, 'طرفا الفولتمتر متصلان بطرفي المصباح، فهو موصول على التوازي معه ويقيس فرق الجهد بين طرفيه.', '["","قياس التيار عمل الأميتر الموصول على التوالي، والجهاز هنا فولتمتر موصول بين طرفي المصباح.","الكمية صحيحة لكن التوصيل خطأ: طرفا الفولتمتر متصلان بطرفي المصباح فهو على التوازي معه.","الجهاز فولتمتر يقيس فرق الجهد لا التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.389Z"}'::jsonb),
('mcq', 6, 3, 'أقصى انحراف يحدث عند تيار ثابت في الملف. ومن $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}}$ فإن $\mathrm{V} = \mathrm{I}\mathrm{R}$؛ فعند زيادة المقاومة الكلية يلزم فرق جهد أكبر لإمرار التيار نفسه، فيزداد أقصى تدريج للفولتمتر.', '["صحيح أن التيار يقل عند الجهد نفسه، لكن هذا يعني أن الوصول إلى أقصى انحراف يحتاج جهدًا أكبر، فيزداد التدريج.","أقصى تيار للملف ثابت فعلًا، لكن الجهد اللازم لإمراره $\\mathrm{V} = \\mathrm{I}\\mathrm{R}$ يزداد بزيادة R.","زيادة المقاومة الكلية تزيد أقصى جهد يقيسه ولا تُنقصه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.389Z"}'::jsonb),
('mcq', 7, 2, 'تُختار مقاومة المضاعف بحيث يمر في الجلفانومتر والمقاومة عند 10 V التيار الذي يُحدث أقصى انحراف، أي تكون المقاومة الكلية $\mathrm{R} = \frac{\mathrm{V}}{\mathrm{I}}$ حيث I تيار الانحراف الأقصى.', '["تساوي المقاومتين لا علاقة له بالتدريج المطلوب؛ المقاومة الكلية تُحدَّد من الجهد وتيار الانحراف الأقصى.","خلط بين وحدتي الجهد والتيار؛ التيار المار صغير جدًّا (ميكروأمبيرات).","","معظم الجهد 10 V يكون بين طرفي المضاعف الكبير، لا بين طرفي الملف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.389Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يوصل الجلفانومتر بمقاومة كبيرة على التوالي تسمى مجزئ الجهد (المضاعف) $R_{\text{مضاعف}}$. يستجيب الملف للتيار المار في المقاومة، ويُحسب بالعلاقة $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}}$ حيث V فرق الجهد بين طرفي الفولتمتر وR المقاومة الكلية (الجلفانومتر والمضاعف)؛ فالتيار يتناسب طرديًّا مع V، فيُدرَّج المؤشر بالفولت. ويوصل الفولتمتر على التوازي مع العنصر، ومقاومته الكلية الكبيرة جدًّا تجعله لا يؤثر في مرور التيار في الدائرة.', '["مقاومة كبيرة على التوالي","اسمها المضاعف (مجزئ الجهد)","الملف يقيس التيار المتناسب مع V حسب I = V/R","يوصل على التوازي ومقاومته الكبيرة لا تؤثر في الدائرة"]'::jsonb, '[]'::jsonb, '[{"element":"المقاومة وطريقة توصيلها","marks":1},{"element":"اسمها","marks":1},{"element":"علاقة التيار بفرق الجهد","marks":1},{"element":"توصيل الفولتمتر وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توصيل المضاعف على التوازي","القول إن الفولتمتر يوصل على التوالي","الخلط بين المضاعف ومجزئ التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-28T06:03:18.389Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المقاومة الكلية للجهاز صغيرة، فعندما يوصل على التوازي مع المصباح يسحب تيارًا كبيرًا من الدائرة، فيغيّر التيار في الدائرة وفرق الجهد بين طرفي المصباح الذي يُراد قياسه، فلا تمثّل قراءته الجهد الأصلي. كما أن التيار الكبير قد يتجاوز التيار الصغير الذي يُحدث أقصى انحراف فيتلف الملف. التعديل: استبدال المقاومة الصغيرة بمقاومة كبيرة جدًّا على التوالي (مضاعف) لتصبح مقاومة الفولتمتر الكلية كبيرة فيسحب تيارًا ضئيلًا.', '["مقاومة الجهاز الكلية صغيرة فيسحب تيارًا كبيرًا","يغيّر الجهد المقيس فتكون القراءة غير صحيحة","التيار الكبير يتجاوز تدريج الملف ويتلفه","استعمال مضاعف كبير على التوالي"]'::jsonb, '[]'::jsonb, '[{"element":"سحب تيار كبير","marks":1},{"element":"تأثيره في القراءة","marks":1},{"element":"خطر تلف الملف","marks":1},{"element":"التعديل الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن أي مقاومة على التوالي تكفي","نسيان أن الفولتمتر يجب ألا يؤثر في الدائرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.389Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجلفانومتران متماثلان فينحرف كل منهما إلى أقصى تدريج عند التيار نفسه I. ومن $\mathrm{V} = \mathrm{I}\mathrm{R}$ يكون الجهد اللازم لأقصى انحراف أكبر في الفولتمتر ذي المقاومة الأكبر، فأقصى تدريج للأول أكبر. وعند الجهد نفسه يسحب الأول تيارًا أصغر ($\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}}$)، فهو أقل تأثيرًا في الدائرة.', '["تيار الانحراف الأقصى واحد للجلفانومترين","الأول أقصى تدريج له أكبر لأن V = IR","الأول يسحب تيارًا أقل فهو أقل تأثيرًا"]'::jsonb, '[]'::jsonb, '[{"element":"ثبات تيار الانحراف الأقصى","marks":1},{"element":"مقارنة أقصى التدريج","marks":1},{"element":"مقارنة التأثير في الدائرة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المقاومة الأكبر تُنقص أقصى تدريج","نسيان أن الجلفانومترين متماثلان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.390Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
