from (values
('mcq', 1, 'ما وظيفة الجزء المرقّم 3 في المحرك الكهربائي الآتي؟', null, '[{"src":"qimg/phys32/c3l2-o11-motor.svg","alt":"مخطط محرك كهربائي بسيط: قطبا مغناطيس، الشمالي N على اليسار والجنوبي S على اليمين، وبينهما خطوط مجال مغناطيسي خضراء B من اليسار إلى اليمين. بين القطبين ملف مستطيل الشكل (حلقة سلكية) يدور حول محور رأسي متقطع. ينتهي طرفا الملف بحلقة معدنية مقسومة إلى نصفين، يلامسها من الجانبين قطعتان صغيرتان متصلتان بسلكين ببطارية. الأجزاء مرقّمة: 1 القطب الشمالي للمغناطيس، 2 الملف، 3 الحلقة المقسومة إلى نصفين، 4 القطعة الملامسة للحلقة من اليسار."}]'::jsonb, '["عكس اتجاه التيار في الملف كل نصف دورة","توليد المجال المغناطيسي بين القطبين","تثبيت محور الدوران ومنع اهتزازه","زيادة مقدار التيار المار في الملف"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 86–87 — المحركات الكهربائية'),
('mcq', 2, 'ماذا يُسمّى الجزء المرقّم 4 في المحرك الكهربائي الآتي، ومن أي مادة يُصنع عادة؟', null, '[{"src":"qimg/phys32/c3l2-o11-motor.svg","alt":"مخطط محرك كهربائي بسيط: قطبا مغناطيس، الشمالي N على اليسار والجنوبي S على اليمين، وبينهما خطوط مجال مغناطيسي خضراء B من اليسار إلى اليمين. بين القطبين ملف مستطيل الشكل (حلقة سلكية) يدور حول محور رأسي متقطع. ينتهي طرفا الملف بحلقة معدنية مقسومة إلى نصفين، يلامسها من الجانبين قطعتان صغيرتان متصلتان بسلكين ببطارية. الأجزاء مرقّمة: 1 القطب الشمالي للمغناطيس، 2 الملف، 3 الحلقة المقسومة إلى نصفين، 4 القطعة الملامسة للحلقة من اليسار."}]'::jsonb, '["عاكس التيار، من الجرافيت","فرشاة، من الجرافيت","فرشاة، من الحديد المطاوع","قلب حديدي، من الحديد المطاوع"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 86–87 — المحركات الكهربائية'),
('mcq', 3, 'لماذا لا تستطيع حلقة سلكية بسيطة يمر فيها تيار ثابت الاتجاه في مجال مغناطيسي أن تدور أكثر من 180°؟', null, null, '["لأن القوتين تنعدمان تمامًا عندما تصبح الحلقة رأسية","لأن المجال المغناطيسي ينعكس كل نصف دورة","لأن النابض يعيدها دائمًا إلى وضعها الأصلي","لأن القوتين تصبحان موازيتين لمستوى الحلقة عندما تصبح رأسية"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 86–87 — المحركات الكهربائية'),
('mcq', 4, 'في أي الوضعين المبيّنين في الشكل الآتي لا تُحدث القوتان المؤثرتان في ضلعي الملف دورانًا، وماذا يلزم عندها لكي يستمر الملف في الدوران؟', null, '[{"src":"qimg/phys32/c3l2-o11-sides.svg","alt":"منظر جانبي لملف (حلقة سلكية) بين خطوط مجال مغناطيسي B أخضر يتجه من اليسار إلى اليمين، في وضعين. (a) الملف أفقي: ضلعه الأيسر يخرج تياره من الورقة (•) وتؤثر فيه قوة F زرقاء إلى أعلى، وضلعه الأيمن يدخل تياره الورقة (×) وتؤثر فيه قوة F إلى أسفل. (b) الملف رأسي: الضلع العلوي تياره داخل الورقة (×) وقوته F إلى أسفل، والضلع السفلي تياره خارج الورقة (•) وقوته F إلى أعلى، أي إن القوتين على امتداد مستوى الملف."}]'::jsonb, '["الوضع (a)، ويلزم عكس اتجاه التيار في الملف","الوضع (b)، ويلزم عكس اتجاه المجال المغناطيسي","الوضع (b)، ويلزم عكس اتجاه التيار في الملف","الوضع (a)، ويلزم زيادة التيار في الملف"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 86–87 — المحركات الكهربائية'),
('mcq', 5, 'كيف يُنتَج المجال المغناطيسي الذي يدور فيه ملف المحرك الكهربائي؟', null, null, '["بمغناطيس دائم أو بمغناطيس كهربائي","بعاكس التيار عند دورانه مع الملف","بالفرشاتين الملامستين لعاكس التيار","بالقلب الحديدي وحده دون تيار أو مغناطيس"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 87 — الملف ذو القلب الحديدي'),
('mcq', 6, 'ملف محرك عدد لفاته $\mathrm{n}$ موضوع في مجال مغناطيسي $\mathrm{B}$. إذا ضوعف عدد اللفات وخُفّض التيار المار فيه إلى النصف، مع بقاء طول السلك في كل لفة داخل المجال ثابتًا، فإن القوة الكلية المؤثرة فيه:', null, null, '["تتضاعف","تقل إلى النصف","تقل إلى الربع","تبقى كما هي"]'::jsonb, 'تطبيق', 'مفاهيمي', 'متوسط', 'الكتاب ص 87 — الملف ذو القلب الحديدي'),
('mcq', 7, 'كيف يُتحكّم في سرعة دوران المحرك الكهربائي؟', null, null, '["بتغيير عدد نصفي عاكس التيار","بتغيير المادة المصنوعة منها الفرشاتان","بتغيير التيار المار في المحرك","بتغيير اتجاه محور الدوران"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 87'),
('essay', 1, 'اعتمادًا على الشكل الآتي، صِف تصميم المحرك الكهربائي البسيط ومبدأ عمله، مبيّنًا: دور كل من الأجزاء المرقّمة 1 و2 و3 و4، وسبب استمرار الملف في الدوران 360°.', null, '[{"src":"qimg/phys32/c3l2-o11-motor.svg","alt":"مخطط محرك كهربائي بسيط: قطبا مغناطيس، الشمالي N على اليسار والجنوبي S على اليمين، وبينهما خطوط مجال مغناطيسي خضراء B من اليسار إلى اليمين. بين القطبين ملف مستطيل الشكل (حلقة سلكية) يدور حول محور رأسي متقطع. ينتهي طرفا الملف بحلقة معدنية مقسومة إلى نصفين، يلامسها من الجانبين قطعتان صغيرتان متصلتان بسلكين ببطارية. الأجزاء مرقّمة: 1 القطب الشمالي للمغناطيس، 2 الملف، 3 الحلقة المقسومة إلى نصفين، 4 القطعة الملامسة للحلقة من اليسار."}]'::jsonb, null, 'فهم', 'مقالي', 'متوسط', 'الكتاب ص 86–87 — المحركات الكهربائية، والشكل 21'),
('essay', 2, 'عندما يتعامد مستوى ملف المحرك مع المجال المغناطيسي لا تُنتج القوى المؤثرة فيه عزمًا. هل يعني هذا أن الملف يتوقف عن الدوران؟ وضّح إجابتك.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 91 — السؤال 28'),
('essay', 3, 'قارن بين الجلفانومتر والمحرك الكهربائي من حيث: (a) أوجه التشابه في التركيب ومبدأ العمل. (b) مقدار دوران الملف في كل منهما وسببه.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 91 — السؤال 27، وص 85–87')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
