select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الجزء 3 حلقة مقسومة إلى نصفين هي عاكس التيار؛ يدور مع الملف فتتبدّل الفرشاة الملامسة لكل نصف عندما يصل الملف إلى الوضع الرأسي، فينعكس اتجاه التيار في الملف كل نصف دورة ويستمر الدوران.', '["","المجال المغناطيسي ينتجه المغناطيس (الجزء 1) لا الحلقة المقسومة.","الحلقة المقسومة جزء كهربائي يوصل التيار، لا دعامة ميكانيكية.","عاكس التيار يغيّر اتجاه التيار لا مقداره؛ ويُتحكّم في التيار بتغيير مصدره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-28T06:03:18.390Z"}'::jsonb),
('mcq', 2, 1, 'الجزء 4 إحدى نقطتي التلامس اللتين تلامسان الحلقة المقسومة وتحافظان على استمرار التوصيل الكهربائي، وتُسمّيان الفرشاتين، ومادتهما في العادة الجرافيت.', '["عاكس التيار هو الحلقة المقسومة (الجزء 3)، لا القطعة الملامسة لها.","","الاسم صحيح، لكن الفرشاتان تُصنعان عادة من الجرافيت.","القلب الحديدي داخل الملف، والجزء 4 قطعة ملامسة لعاكس التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-28T06:03:18.390Z"}'::jsonb),
('mcq', 3, 3, 'تدفع القوة أحد جانبي الحلقة إلى أعلى والآخر إلى أسفل حتى تصبح الحلقة رأسية؛ عندها تبقى القوتان إلى أعلى وإلى أسفل، أي موازيتين لمستوى الحلقة، فلا تعودان قادرتين على إحداث دوران.', '["القوتان لا تنعدمان؛ يبقى مقدارهما ثابتًا لكن اتجاههما أصبح على امتداد مستوى الحلقة فلا يُحدثان دورانًا.","المجال المغناطيسي للمغناطيس الدائم ثابت الاتجاه؛ الذي يجب أن ينعكس هو التيار.","النابض جزء من الجلفانومتر، لا من الحلقة في المحرك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-28T06:03:18.390Z"}'::jsonb),
('mcq', 4, 2, 'في الوضع (b) تقع القوتان على امتداد مستوى الملف فلا تُديرانه. ولكي يواصل الدوران يجب أن ينعكس اتجاه التيار في الملف عندما يصبح رأسيًّا، فينعكس اتجاه القوتين ويستمر الدوران؛ وهذا ما يفعله عاكس التيار.', '["في الوضع (a) القوتان عموديتان على مستوى الملف ومتعاكستان فتُحدثان دورانًا.","الوضع صحيح، لكن المحرك يعكس التيار بعاكس التيار والفرشاتين لا المجال المغناطيسي.","","الوضع (a) هو الذي تُحدث فيه القوتان دورانًا، وزيادة التيار لا تحل مشكلة الوضع الرأسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('mcq', 5, 0, 'يدور ملف المحرك في مجال مغناطيسي يُنتَج إما بمغناطيس دائم، أو بمغناطيس كهربائي.', '["","عاكس التيار حلقة مقسومة تعكس اتجاه التيار في الملف كل نصف دورة، ولا تُنتج المجال.","الفرشاتان نقطتا تلامس تحافظان على استمرار التوصيل الكهربائي، ولا تُنتجان المجال.","القلب الحديدي يُلف عليه الملف، ولا يُنتج وحده مجالًا دون مغناطيس دائم أو تيار كهربائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('mcq', 6, 3, 'القوة الكلية في ملف المحرك تتناسب طرديًّا مع $\mathrm{nILB}$؛ مضاعفة $\mathrm{n}$ تضاعف القوة، وتنصيف $\mathrm{I}$ يُنصّفها، فتبقى القوة كما هي.', '["أخذ أثر مضاعفة اللفات فقط وأهمل نقص التيار.","أخذ أثر نقص التيار فقط وأهمل مضاعفة اللفات.","عامل نقص التيار ومضاعفة اللفات كأن كليهما يُنقص القوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('mcq', 7, 2, 'يُتحكّم في العزم المؤثر في الملف، ومن ثم في سرعة المحرك، بتغيير التيار المار فيه؛ لأن القوة تتناسب طرديًّا مع التيار.', '["عاكس التيار نصفان دائمًا ووظيفته عكس اتجاه التيار، لا التحكم في السرعة.","مادة الفرشاتين (الجرافيت) لا تُستعمل للتحكم في السرعة.","","محور الدوران مثبّت، وتغيير اتجاهه لا يتحكم في سرعة الدوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجزء 1 مغناطيس (قطباه N وS) يُنتج مجالًا مغناطيسيًّا. الجزء 2 ملف (حلقة سلكية) يمر فيه تيار، فيتأثر ضلعاه بقوتين متعاكستين (إحداهما إلى أعلى والأخرى إلى أسفل) فيدور حول محوره. الجزء 3 عاكس التيار: حلقة مقسومة إلى نصفين تدور مع الملف. الجزء 4 فرشاة من الجرافيت (ومعها فرشاة أخرى) تلامس عاكس التيار وتحافظ على استمرار التوصيل الكهربائي. عندما يصل الملف إلى الوضع الرأسي تتبدّل الفرشاة الملامسة لكل نصف، فينعكس التيار في الملف وتنعكس القوتان، فيواصل الملف دورانه؛ ويتكرر ذلك كل نصف دورة فيدور 360°، ويتحول بذلك جزء من الطاقة الكهربائية إلى طاقة حركية دورانية.', '["المغناطيس يُنتج المجال","الملف يتأثر بقوتين متعاكستين فيدور","عاكس التيار والفرشاتان يعكسان التيار كل نصف دورة مع استمرار التوصيل","انعكاس التيار في الوضع الرأسي يسمح بالدوران 360°"]'::jsonb, '[]'::jsonb, '[{"element":"دور المغناطيس","marks":1},{"element":"دور الملف والقوتين","marks":1},{"element":"دور عاكس التيار والفرشاتين","marks":1},{"element":"تفسير الدوران الكامل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عاكس التيار يعكس المجال المغناطيسي","إغفال دور الفرشاتين في استمرار التوصيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لا يتوقف. في هذا الوضع تكون القوتان على امتداد مستوى الملف فلا تُنتجان عزمًا، لكن الملف يكون متحركًا فيستمر في دورانه بسبب حركته (قصوره الذاتي) متجاوزًا هذا الوضع. وفي اللحظة نفسها يعكس عاكس التيار اتجاه التيار، فتعود القوتان إلى إنتاج عزم في اتجاه الدوران نفسه فيستمر الدوران.', '["لا يتوقف الملف","يتجاوز الوضع بسبب حركته","عاكس التيار يعكس التيار فيعود العزم في اتجاه الدوران"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تعليل تجاوز الوضع","marks":1},{"element":"دور عاكس التيار","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن انعدام العزم يعني التوقف الفوري","نسيان دور عاكس التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.391Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) كلاهما يحتوي على ملف (حلقة سلكية) يمر فيه تيار وموضوع في مجال مغناطيسي، ويتأثر ضلعاه بقوتين متعاكستين تُديرانه. (b) في الجلفانومتر يؤثر نابض صغير بعزم معاكس فيدور الملف دورانًا محدودًا يتناسب طرديًّا مع التيار، ولا يدور أكثر من 180°. أما في المحرك فيعكس عاكس التيار والفرشاتان اتجاه التيار كل نصف دورة فيدور الملف دورانًا كاملًا 360° باستمرار.', '["كلاهما ملف يمر فيه تيار في مجال مغناطيسي فيتأثر بعزم","الجلفانومتر فيه نابض فدورانه محدود ومتناسب مع التيار","المحرك فيه عاكس تيار فيدور دورانًا كاملًا"]'::jsonb, '[]'::jsonb, '[{"element":"أوجه التشابه","marks":1},{"element":"دوران الجلفانومتر وسببه","marks":1},{"element":"دوران المحرك وسببه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجلفانومتر يحتوي على عاكس تيار","إغفال دور النابض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-28T06:03:18.392Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O11') and x.type = v.type and x.number = v.number
