insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'على أيّ العوامل الآتية تعتمد القوة المغناطيسية المؤثرة في جسيم مشحون يتحرك عموديًّا على مجال مغناطيسي؟', null, null, '["كتلة الجسيم وشحنته ومقدار المجال المغناطيسي","سرعة الجسيم وشحنته ومقدار المجال المغناطيسي","سرعة الجسيم وكتلته وطول مساره في المجال","شحنة الجسيم وكتلته والمجال الكهربائي"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 95 — المفاهيم الرئيسة، وص 89'),
('mcq', 2, 'ما العلاقة التي تعطي مقدار القوة التي يؤثر بها مجال مغناطيسي في جسيم مشحون متحرك سرعته تصنع زاوية $\theta$ مع المجال؟', null, null, '["$F = qv\\mathrm{B}\\,(\\sin\\theta)$","$F = qv\\mathrm{B}\\,(\\cos\\theta)$","$F = \\mathrm{ILB}\\,(\\sin\\theta)$","$F = \\frac{qv}{\\mathrm{B}}\\,(\\sin\\theta)$"]'::jsonb, 'تذكر', 'علاقات وقوانين', 'متوسط', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('mcq', 3, 'أيّ الجسيمات الموجبة الأربعة في الشكل الآتي تتأثر بأكبر قوة مغناطيسية؟', null, '[{"src":"qimg/phys32/c3l2-o12-angles.svg","alt":"مجال مغناطيسي منتظم B تمثله خطوط خضراء أفقية تتجه نحو اليمين. فيه أربعة جسيمات موجبة الشحنة متماثلة، تتحرك بالسرعة نفسها v (أسهم حمراء): الجسيم (1) يتحرك نحو اليمين موازيًا للمجال، والجسيم (2) يتحرك إلى أعلى عموديًّا على المجال، والجسيم (3) يتحرك بزاوية 30° فوق اتجاه المجال، والجسيم (4) يتحرك نحو اليسار عكس اتجاه المجال."}]'::jsonb, '["الجسيم (1)","الجسيم (3)","الجسيم (4)","الجسيم (2)"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('mcq', 4, 'أيّ الجسيمات الآتية لا يتأثر بقوة مغناطيسية عند دخوله مجالًا مغناطيسيًّا عموديًّا على اتجاه سرعته؟', null, null, '["الإلكترون","البروتون","النيوترون","جسيم ألفا"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('mcq', 5, 'إذا ضوعفت سرعة إلكترون يتحرك عموديًّا على مجال مغناطيسي منتظم، مع بقاء المجال ثابتًا، فإن القوة المغناطيسية المؤثرة فيه:', null, null, '["تتضاعف إلى مثليها","تبقى كما هي","تقل إلى النصف","تصبح أربعة أمثالها"]'::jsonb, 'فهم', 'مفاهيمي', 'سهل', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('mcq', 6, 'بروتون وإلكترون يتحركان بالسرعة نفسها عموديًّا على المجال المغناطيسي نفسه. ما العلاقة بين مقداري القوتين المؤثرتين فيهما؟', null, null, '["القوة في الإلكترون أكبر لأن كتلته أصغر","القوة في البروتون أكبر لأن كتلته أكبر","متساويتان في المقدار","القوة في الإلكترون صفر لأن شحنته سالبة"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('mcq', 7, 'جسيم مشحون موضوع ساكنًا داخل مجال مغناطيسي منتظم. ما مقدار القوة المغناطيسية المؤثرة فيه؟', null, null, '["$q\\mathrm{B}$، لأن الشحنة داخل المجال","تعتمد على كتلة الجسيم","عظمى، لأن الجسيم لا يتحرك","صفر، لأن سرعته صفر"]'::jsonb, 'فهم', 'مفاهيمي', 'صعب', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('essay', 1, 'اذكر العوامل التي تعتمد عليها القوة المغناطيسية المؤثرة في جسيم مشحون يتحرك داخل مجال مغناطيسي، واكتب العلاقة الرياضية التي تربطها مع وحدة كل كمية، ثم اذكر متى تكون القوة عظمى ومتى تنعدم.', null, null, null, 'تذكر', 'مقالي', 'سهل', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون، وص 95'),
('essay', 2, 'في تجربة، قيست القوة المغناطيسية المؤثرة في أيون يتحرك عموديًّا على مجال مغناطيسي ثابت بسرعات مختلفة، فكانت النتائج كما في الجدول الآتي. (a) ما العلاقة بين القوة والسرعة؟ (b) أي العاملين بقي ثابتًا في التجربة غير المجال؟ (c) ما القوة المتوقعة عند سرعة $5.0\times10^{5}\ \text{m/s}$؟', '{"headers":["السرعة $v$ (m/s)","القوة $F$ (N)"],"rows":[["$1.0\\times10^{5}$","$8.0\\times10^{-16}$"],["$2.0\\times10^{5}$","$1.6\\times10^{-15}$"],["$3.0\\times10^{5}$","$2.4\\times10^{-15}$"],["$4.0\\times10^{5}$","$3.2\\times10^{-15}$"]]}'::jsonb, null, null, 'تحليل', 'مقالي', 'متوسط', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون'),
('essay', 3, 'اعتمادًا على الشكل الآتي، رتّب الجسيمات الأربعة تصاعديًّا حسب مقدار القوة المغناطيسية المؤثرة في كل منها، وفسّر إجابتك باستعمال العوامل المؤثرة في القوة. ما نسبة القوة في الجسيم (3) إلى القوة في الجسيم (2)؟', null, '[{"src":"qimg/phys32/c3l2-o12-angles.svg","alt":"مجال مغناطيسي منتظم B تمثله خطوط خضراء أفقية تتجه نحو اليمين. فيه أربعة جسيمات موجبة الشحنة متماثلة، تتحرك بالسرعة نفسها v (أسهم حمراء): الجسيم (1) يتحرك نحو اليمين موازيًا للمجال، والجسيم (2) يتحرك إلى أعلى عموديًّا على المجال، والجسيم (3) يتحرك بزاوية 30° فوق اتجاه المجال، والجسيم (4) يتحرك نحو اليسار عكس اتجاه المجال."}]'::jsonb, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 88–89 — القوة المؤثرة في جسيم مشحون')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
