insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تعتمد القوة التي يؤثر بها المجال المغناطيسي في جسيم مشحون على ثلاثة عوامل: سرعة الجسيم وشحنته ومقدار المجال المغناطيسي، حسب العلاقة $F = qv\mathrm{B}$.', '["الكتلة ليست من عوامل القوة المغناطيسية؛ القوة تعتمد على السرعة لا الكتلة.","","لا تعتمد القوة على الكتلة ولا على طول المسار، بل على الشحنة والمجال المغناطيسي والسرعة.","المجال الكهربائي والكتلة ليسا من عوامل القوة المغناطيسية، وأُهملت السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-28T06:03:18.392Z"}'::jsonb),
('mcq', 2, 0, 'القوة التي يؤثر بها المجال المغناطيسي في جسيم مشحون متحرك: $F = qv\mathrm{B}\,(\sin\theta)$، وعند التعامد تصبح $F = qv\mathrm{B}$.', '["","القوة عظمى عند التعامد (90°) وتنعدم عند التوازي، وهذا يوافق الجيب لا جيب التمام.","هذه علاقة القوة المؤثرة في سلك يسري فيه تيار، لا في جسيم مشحون منفرد.","القوة تتناسب طرديًّا مع المجال لا عكسيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-28T06:03:18.392Z"}'::jsonb),
('mcq', 3, 3, 'الجسيمات متماثلة الشحنة والسرعة في المجال نفسه، فالفرق في الزاوية فقط. من $F = qv\mathrm{B}\,(\sin\theta)$ تكون القوة عظمى عندما $\theta = 90^\circ$، أي للجسيم (2) الذي يتحرك عموديًّا على المجال.', '["سرعته موازية للمجال ($\\theta = 0^\\circ$) فالقوة المؤثرة فيه صفر.","زاويته $30^\\circ$ فالقوة فيه نصف القوة العظمى فقط ($\\sin 30^\\circ = 0.5$).","سرعته عكس المجال ($\\theta = 180^\\circ$) فالقوة المؤثرة فيه صفر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-28T06:03:18.393Z"}'::jsonb),
('mcq', 4, 2, 'من $F = qv\mathrm{B}$، إذا كانت الشحنة صفرًا كانت القوة صفرًا؛ والنيوترون متعادل الشحنة فلا يتأثر بقوة مغناطيسية.', '["الإلكترون مشحون بشحنة سالبة فيتأثر بقوة.","البروتون مشحون بشحنة موجبة فيتأثر بقوة.","","جسيم ألفا (ذرة هيليوم ثنائية التأين) يحمل شحنة موجبة فيتأثر بقوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-28T06:03:18.393Z"}'::jsonb),
('mcq', 5, 0, 'من $F = qv\mathrm{B}$ تتناسب القوة طرديًّا مع السرعة $v$، فمضاعفة السرعة تضاعف القوة.', '["","القوة تعتمد على السرعة، فلا تبقى ثابتة عند تغيّرها.","القوة تتناسب طرديًّا مع السرعة لا عكسيًّا.","القوة تتناسب مع السرعة لا مع مربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-28T06:03:18.393Z"}'::jsonb),
('mcq', 6, 2, 'مقدار شحنة البروتون يساوي مقدار شحنة الإلكترون ($1.60\times10^{-19}\ \text{C}$)، والسرعة والمجال متساويان، فمن $F = qv\mathrm{B}$ تتساوى القوتان مقدارًا، وتختلفان في الاتجاه فقط.', '["الكتلة ليست من عوامل القوة المغناطيسية.","الكتلة ليست من عوامل القوة المغناطيسية.","","الشحنة السالبة تعكس اتجاه القوة فقط ولا تلغيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.393Z"}'::jsonb),
('mcq', 7, 3, 'من $F = qv\mathrm{B}$، إذا كانت $v = 0$ كانت $F = 0$؛ فالمجال المغناطيسي لا يؤثر بقوة في شحنة ساكنة.', '["القوة المغناطيسية تتطلب حركة الشحنة؛ العلاقة تتضمن السرعة $v$.","الكتلة ليست من عوامل القوة المغناطيسية.","العكس: انعدام السرعة يعني انعدام القوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-28T06:03:18.393Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعتمد القوة على سرعة الجسيم $v$ وشحنته $q$ ومقدار المجال المغناطيسي $\mathrm{B}$ (والزاوية $\theta$ بين متجه السرعة واتجاه المجال)، حسب العلاقة $F = qv\mathrm{B}\,(\sin\theta)$، حيث $q$ بالكولوم C، و$v$ بوحدة m/s، و$\mathrm{B}$ بالتسلا T، و$F$ بالنيوتن N. تكون القوة عظمى ($F = qv\mathrm{B}$) عندما تتحرك الشحنة عموديًّا على المجال، وتنعدم عندما تتحرك موازية للمجال أو تكون ساكنة.', '["العوامل: السرعة والشحنة والمجال (والزاوية)","العلاقة $F = qv\\mathrm{B}\\,(\\sin\\theta)$ مع الوحدات","القوة عظمى عند التعامد","تنعدم عند التوازي أو السكون"]'::jsonb, '[]'::jsonb, '[{"element":"العوامل","marks":1},{"element":"العلاقة والوحدات","marks":1},{"element":"حالة القوة العظمى","marks":1},{"element":"حالة انعدام القوة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الكتلة عاملًا","استعمال جيب التمام بدل الجيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.394Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند مضاعفة السرعة تتضاعف القوة، وعند جعلها ثلاثة أمثالها تصبح القوة ثلاثة أمثالها؛ فالقوة تتناسب طرديًّا مع السرعة ($\frac{F}{v} = 8.0\times10^{-21}\ \text{N.s/m}$ ثابت). (b) شحنة الأيون (لأنه الأيون نفسه). (c) $F = (8.0\times10^{-21})(5.0\times10^{5}) = 4.0\times10^{-15}\ \text{N}$.', '["القوة تتناسب طرديًّا مع السرعة","الشحنة ثابتة","القوة المتوقعة $4.0\\times10^{-15}\\ \\text{N}$"]'::jsonb, '["$\\frac{F}{v} = \\frac{8.0\\times10^{-16}}{1.0\\times10^{5}} = 8.0\\times10^{-21}$ للصفوف كلها","$F = (8.0\\times10^{-21})(5.0\\times10^{5}) = 4.0\\times10^{-15}\\ \\text{N}$"]'::jsonb, '[{"element":"العلاقة الطردية","marks":1},{"element":"العامل الثابت","marks":1},{"element":"القيمة المتوقعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف العلاقة بأنها عكسية","الخطأ في الأسس العشرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-28T06:03:18.394Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الشحنة والسرعة والمجال متساوية، والاختلاف في الزاوية $\theta$ بين السرعة والمجال. من $F = qv\mathrm{B}\,(\sin\theta)$: الجسيمان (1) ($\theta = 0^\circ$) و(4) ($\theta = 180^\circ$) القوة فيهما صفر، والجسيم (3) ($\theta = 30^\circ$) القوة فيه $0.5\,qv\mathrm{B}$، والجسيم (2) ($\theta = 90^\circ$) القوة فيه عظمى $qv\mathrm{B}$. الترتيب: (1) = (4) < (3) < (2)، ونسبة القوة في (3) إلى (2) تساوي $\sin 30^\circ = 0.5$.', '["العوامل الثابتة والزاوية المتغيرة","(1) و(4) القوة صفر","(3) نصف القوة العظمى و(2) القوة العظمى","الترتيب والنسبة 0.5"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العامل المتغير","marks":1},{"element":"حالتا الصفر","marks":1},{"element":"القوة في (3) و(2)","marks":1},{"element":"الترتيب والنسبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الجسيم (4) متأثرًا بأكبر قوة لأنه يتحرك عكس المجال","استعمال $\\cos 30^\\circ$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-28T06:03:18.394Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
