('mcq', 1, 'عند استخدام القاعدة الثالثة لليد اليمنى لتحديد اتجاه القوة المؤثرة في جسيم موجب الشحنة يتحرك في مجال مغناطيسي، إلى أين يشير الإبهام؟', null, null, '["إلى اتجاه المجال المغناطيسي","إلى اتجاه سرعة الجسيم","إلى اتجاه القوة المؤثرة في الجسيم","عكس اتجاه سرعة الجسيم"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون، وص 82'),
('mcq', 2, 'ما اتجاه القوة المغناطيسية المؤثرة في جسيم مشحون يتحرك في مجال مغناطيسي بالنسبة إلى سرعته وإلى المجال؟', null, null, '["عمودي على كل من اتجاه السرعة واتجاه المجال","في اتجاه المجال المغناطيسي دائمًا","في اتجاه سرعة الجسيم دائمًا","عمودي على السرعة وموازٍ للمجال"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('mcq', 3, 'يتحرك بروتون في المجال المغناطيسي المبيّن في الشكل الآتي. عند تطبيق القاعدة الثالثة لليد اليمنى عليه، إلى أين تُوجَّه أصابع اليد اليمنى؟', null, '[{"src":"qimg/phys32/c3l2-o13-proton.svg","alt":"مجال مغناطيسي منتظم B داخل في مستوى الورقة تمثله علامات × خضراء موزعة بانتظام. بروتون (دائرة فيها +) يتحرك بسرعة v (سهم أحمر) نحو اليمين في مستوى الورقة."}]'::jsonb, '["نحو اليمين في اتجاه حركة البروتون","نحو أعلى الصفحة","نحو خارج الورقة","نحو داخل الورقة"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('mcq', 4, 'يتحرك إلكترون نحو أعلى الصفحة داخل مجال مغناطيسي خارج من الورقة كما في الشكل الآتي. أيّ الاتجاهات الآتية يتأثر نحوه بالقوة المغناطيسية؟', null, '[{"src":"qimg/phys32/c3l2-o13-electron.svg","alt":"مجال مغناطيسي منتظم B خارج من مستوى الورقة تمثله نقاط • خضراء موزعة بانتظام. إلكترون (دائرة فيها −) يتحرك بسرعة v (سهم أحمر) نحو أعلى الصفحة في مستوى الورقة."}]'::jsonb, '["نحو اليمين","نحو أعلى الصفحة","نحو اليسار","نحو خارج الورقة"]'::jsonb, 'تطبيق', 'مفاهيمي', 'صعب', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('mcq', 5, 'عند استخدام القاعدة الثالثة لليد اليمنى لإلكترون يتحرك عموديًّا على مجال مغناطيسي بحيث يعطي باطن الكف اتجاه القوة المؤثرة فيه مباشرة، إلى أي اتجاه يجب أن يشير الإبهام؟', null, null, '["عكس اتجاه حركة الإلكترون","في اتجاه حركة الإلكترون","في اتجاه المجال المغناطيسي","عكس اتجاه المجال المغناطيسي"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 90 — مسائل تدريبية: السؤال 20'),
('mcq', 6, 'تتحرك حزمة بروتونات أفقيًّا من الخلف إلى الأمام في غرفة، فانحرفت إلى أعلى عندما أثّر فيها مجال مغناطيسي أفقي. ما اتجاه هذا المجال بالنسبة إلى راصد ينظر في اتجاه حركة البروتونات؟', null, null, '["نحو يمين الراصد","رأسيًّا إلى أسفل","في اتجاه حركة البروتونات","نحو يسار الراصد"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 97 — السؤال 56'),
('mcq', 7, 'يتحرك جسيم موجب الشحنة في مجال مغناطيسي فيتأثر بقوة نحو الشرق. إذا استُبدل به جسيم سالب الشحنة يتحرك بالسرعة نفسها وفي الاتجاه نفسه، وعُكس اتجاه المجال، فما اتجاه القوة المؤثرة فيه؟', null, null, '["نحو الغرب","نحو الشمال","نحو الشرق","تنعدم القوة"]'::jsonb, 'تحليل', 'مفاهيمي', 'متوسط', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('essay', 1, 'وضّح كيف تُستخدم القاعدة الثالثة لليد اليمنى لتحديد اتجاه القوة المغناطيسية المؤثرة في جسيم مشحون متحرك في مجال مغناطيسي: ما الذي تمثله الأصابع والإبهام وباطن الكف؟ وكيف يختلف الحكم إذا كان الجسيم إلكترونًا؟ وما علاقة اتجاه القوة باتجاهي السرعة والمجال؟', null, null, null, 'فهم', 'مقالي', 'سهل', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('essay', 2, 'يتحرك بروتون وإلكترون بالسرعة نفسها كما في الشكل الآتي، ويدخلان المجال المغناطيسي نفسه. (a) حدّد اتجاه القوة المؤثرة في كل منهما لحظة دخولهما المجال، مبيّنًا خطوات تطبيق القاعدة. (b) قارن بين مقداري القوتين.', null, '[{"src":"qimg/phys32/c3l2-o13-pair.svg","alt":"على يسار خط متقطع بروتون (+) في الأعلى وإلكترون (−) في الأسفل، يتحرك كل منهما بالسرعة نفسها v (سهم أحمر) نحو اليمين، ويوشكان أن يدخلا منطقة على يمين الخط فيها مجال مغناطيسي منتظم B داخل في مستوى الورقة (علامات × خضراء)."}]'::jsonb, null, 'تطبيق', 'مقالي', 'متوسط', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون'),
('essay', 3, 'يتحرك إلكترون نحو الشرق أفقيًّا في مجال مغناطيسي أفقي يتجه نحو الشمال. حدّد اتجاه القوة المغناطيسية المؤثرة فيه، موضّحًا خطوات استعمال القاعدة الثالثة لليد اليمنى، ثم بيّن كيف يتغير اتجاه القوة لو كان الجسيم بروتونًا.', null, null, null, 'تطبيق', 'مقالي', 'صعب', 'الكتاب ص 89 — اتجاه القوة المؤثرة في جسيم مشحون، وص 82')
