from (values
('mcq', 1, 1, 'في القاعدة الثالثة لليد اليمنى تُجعل الأصابع في اتجاه المجال المغناطيسي، والإبهام في اتجاه سرعة الجسيم الموجب (كالتيار الاصطلاحي)، فيكون اتجاه القوة عموديًّا على باطن الكف نحو الخارج.', '["الأصابع هي التي تشير إلى اتجاه المجال المغناطيسي.","","اتجاه القوة هو العمودي على باطن الكف نحو الخارج، لا اتجاه الإبهام.","عكس اتجاه السرعة يخص حالة الإلكترون، أما الجسيم الموجب فيشير الإبهام إلى اتجاه حركته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-28T06:03:18.395Z"}'::jsonb),
('mcq', 2, 0, 'اتجاه القوة المغناطيسية عمودي دائمًا على كل من اتجاه السرعة واتجاه المجال، فهي لا توازي أيًّا منهما.', '["","القوة المغناطيسية ليست في اتجاه المجال؛ هذا يخلط بينها وبين القوة الكهربائية على شحنة في مجال كهربائي.","القوة لا تكون في اتجاه السرعة، وإلا لتغيّرت سرعة الجسيم مقدارًا.","القوة عمودية على المجال أيضًا، لا موازية له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-28T06:03:18.395Z"}'::jsonb),
('mcq', 3, 3, 'في القاعدة الثالثة لليد اليمنى تُجعل الأصابع في اتجاه المجال المغناطيسي، والمجال في الشكل داخل في الورقة (علامات ×)، فتُوجَّه الأصابع نحو داخل الورقة، والإبهام نحو اليمين في اتجاه حركة البروتون.', '["اتجاه حركة الشحنة الموجبة يمثله الإبهام لا الأصابع.","أعلى الصفحة هو الاتجاه العمودي على باطن الكف (اتجاه القوة على البروتون)، لا اتجاه الأصابع.","علامة × تعني أن المجال داخل في الورقة؛ الخارج منها يُرمز إليه بالرمز •.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.395Z"}'::jsonb),
('mcq', 4, 2, 'الأصابع نحو خارج الورقة (المجال) والإبهام نحو أعلى الصفحة (اتجاه الحركة) فينتج اتجاه نحو اليمين، وهو خاص بالشحنة الموجبة؛ ولأن شحنة الإلكترون سالبة تكون القوة المؤثرة فيه معاكسة، أي نحو اليسار.', '["هذا الاتجاه الناتج من القاعدة مباشرة، وهو خاص بالشحنة الموجبة؛ نسي عكسه للإلكترون.","القوة عمودية على السرعة، والإلكترون يتحرك نحو أعلى الصفحة.","","القوة عمودية على المجال الخارج من الورقة، فلا تكون نحو خارجها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-28T06:03:18.395Z"}'::jsonb),
('mcq', 5, 0, 'حركة الإلكترون في اتجاه ما تكافئ تيارًا اصطلاحيًّا في الاتجاه المعاكس، فإذا جُعل الإبهام عكس اتجاه حركة الإلكترون والأصابع في اتجاه المجال أعطى باطن الكف اتجاه القوة الفعلية المؤثرة في الإلكترون.', '["","هذا يعطي اتجاه القوة على شحنة موجبة، أي عكس القوة الفعلية على الإلكترون.","الأصابع هي التي تشير إلى المجال لا الإبهام.","الإبهام يمثل حركة الشحنة لا المجال، والمجال تمثله الأصابع في اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-28T06:03:18.396Z"}'::jsonb),
('mcq', 6, 3, 'القوة عمودية على المجال وعلى السرعة. بتطبيق القاعدة الثالثة لليد اليمنى للبروتون الموجب: الإبهام إلى الأمام (السرعة)، وباطن الكف يجب أن يواجه أعلى (القوة)، فتشير الأصابع نحو يسار الراصد، وهذا اتجاه المجال.', '["هذا الاتجاه يجعل القوة على البروتونات إلى أسفل لا إلى أعلى.","المجال الرأسي يُنتج قوة أفقية (يمينًا أو يسارًا) لا قوة إلى أعلى.","المجال الموازي للسرعة لا يؤثر بأي قوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-28T06:03:18.396Z"}'::jsonb),
('mcq', 7, 2, 'عكس إشارة الشحنة يعكس اتجاه القوة، وعكس اتجاه المجال يعكسها مرة أخرى؛ فيعود اتجاه القوة كما كان: نحو الشرق.', '["عكس الشحنة وحده يعكس القوة، لكن عكس المجال أيضًا يعيدها إلى اتجاهها الأصلي.","القوة تبقى عمودية على السرعة والمجال فلا تدور 90°.","","القوة لا تنعدم؛ السرعة ما زالت عمودية على المجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.396Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُجعل أصابع اليد اليمنى في اتجاه المجال المغناطيسي، والإبهام في اتجاه سرعة الجسيم (للشحنة الموجبة)، فيكون اتجاه القوة هو العمودي على باطن الكف نحو الخارج. هذا الاتجاه خاص بالجسيمات الموجبة؛ أما الإلكترون فتكون القوة المؤثرة فيه معاكسة للاتجاه الناتج. والقوة دائمًا عمودية على كل من اتجاه السرعة واتجاه المجال.', '["الأصابع في اتجاه المجال","الإبهام في اتجاه سرعة الشحنة الموجبة","القوة عمودية على باطن الكف نحو الخارج","القوة على الإلكترون معاكسة، والقوة عمودية على السرعة والمجال"]'::jsonb, '[]'::jsonb, '[{"element":"الأصابع","marks":1},{"element":"الإبهام","marks":1},{"element":"باطن الكف واتجاه القوة","marks":1},{"element":"حالة الإلكترون والتعامد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الأصابع في اتجاه السرعة","نسيان عكس الاتجاه للإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.396Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) البروتون: الأصابع نحو داخل الورقة (المجال)، والإبهام نحو اليمين (السرعة)، فيكون العمودي على باطن الكف نحو أعلى الصفحة؛ فالقوة على البروتون نحو أعلى الصفحة. الإلكترون: شحنته سالبة فالقوة عليه معاكسة للاتجاه الناتج من القاعدة، أي نحو أسفل الصفحة. فينحرف البروتون إلى أعلى والإلكترون إلى أسفل. (b) مقدارا شحنتيهما متساويان والسرعة والمجال متساويان، فمن $F = qv\mathrm{B}$ القوتان متساويتان مقدارًا ومتعاكستان اتجاهًا.', '["تطبيق القاعدة على البروتون: القوة نحو أعلى الصفحة","الإلكترون: القوة معاكسة نحو أسفل الصفحة","تساوي المقدارين لتساوي مقداري الشحنتين"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه القوة على البروتون مع الخطوات","marks":1},{"element":"اتجاه القوة على الإلكترون","marks":1},{"element":"مقارنة المقدارين","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء الجسيمين الاتجاه نفسه","القول إن القوة على الإلكترون أكبر لصغر كتلته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-28T06:03:18.397Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نطبّق القاعدة أولًا كأن الشحنة موجبة: الأصابع نحو الشمال (المجال)، والإبهام نحو الشرق (السرعة)، فيكون العمودي على باطن الكف نحو أعلى (رأسيًّا إلى أعلى). ولأن الإلكترون سالب الشحنة تكون القوة المؤثرة فيه معاكسة: رأسيًّا إلى أسفل. ولو كان الجسيم بروتونًا لكانت القوة رأسيًّا إلى أعلى.', '["الأصابع نحو الشمال والإبهام نحو الشرق","الاتجاه الناتج للشحنة الموجبة: إلى أعلى","القوة على الإلكترون: إلى أسفل","للبروتون: إلى أعلى"]'::jsonb, '[]'::jsonb, '[{"element":"وضع الأصابع والإبهام","marks":1},{"element":"الاتجاه الناتج","marks":1},{"element":"عكسه للإلكترون","marks":1},{"element":"حالة البروتون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء القوة اتجاهًا أفقيًّا","نسيان عكس الاتجاه للإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-28T06:03:18.397Z"}'::jsonb)
