('mcq', 5, 'أيّ القاعدتين تُستخدمان لتفسير التجاذب بين سلكين متوازيين يسري فيهما تياران في الاتجاه نفسه؟', null, null, '["الأولى لتحديد المجال، والثالثة لتحديد القوة","الأولى لتحديد القوة، والثالثة لتحديد المجال","الثانية لتحديد المجال، والثالثة لتحديد القوة","الثالثة وحدها لتحديد المجال والقوة معًا"]'::jsonb, 'فهم', 'مفاهيمي', 'سهل', 'الكتاب ص 82 — القوى بين سلكين يسري فيهما تياران (الشكل 17)'),
('mcq', 6, 'كيف يمكن التأكد من أن القوة بين سلكين متوازيين يسري فيهما تياران قوة مغناطيسية لا كهربائية سكونية؟', null, null, '["تزداد كلما اقترب السلكان أحدهما من الآخر","تظهر حتى عند انقطاع التيار في السلكين","تجعل السلكين يتجاذبان في جميع الحالات","تنقلب من تجاذب إلى تنافر بعكس أحد التيارين فقط"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 91 — السؤال 30'),
('mcq', 7, 'ثلاثة أسلاك متوازية متساوية التباعد يسري فيها تيارات متساوية في الاتجاه نفسه، كما في الشكل الآتي. ما محصلة القوى المغناطيسية المؤثرة في السلك الأوسط (2)؟', null, '[{"src":"qimg/phys32/c3l2-o14-three.svg","alt":"ثلاثة أسلاك مستقيمة رأسية متوازية في مستوى الورقة: (1) على اليسار، و(2) في الوسط، و(3) على اليمين، والمسافة بين كل سلكين متجاورين d. يسري في كل منها تيار I متساوٍ نحو أعلى الصفحة."}]'::jsonb, '["قوة نحو السلك (1)","قوة نحو السلك (3)","محصلة القوى صفر","ضعف القوة بين سلكين متجاورين"]'::jsonb, 'تحليل', 'مفاهيمي', 'متوسط', 'الكتاب ص 91 — السؤال 30 (التنبيه)'),
('essay', 1, 'اعتمادًا على الشكل الآتي، فسّر لماذا يتجاذب السلكان المتوازيان اللذان يسري فيهما تياران في الاتجاه نفسه، مستخدمًا القاعدة الأولى لليد اليمنى والقاعدة الثالثة لليد اليمنى، ومبيّنًا اتجاه المجال واتجاه القوة على كل سلك.', null, '[{"src":"qimg/phys32/c3l2-o14-same.svg","alt":"سلكان مستقيمان رأسيان متوازيان في مستوى الورقة، السلك (1) على اليسار والسلك (2) على اليمين، والمسافة بينهما d. يسري في كل منهما تيار I نحو أعلى الصفحة (سهم بجانب كل سلك)."}]'::jsonb, null, 'فهم', 'مقالي', 'متوسط', 'الكتاب ص 82 — القوى بين سلكين يسري فيهما تياران (الشكل 17)'),
('essay', 2, 'في الشكل الآتي يسري في السلكين المتوازيين تياران متعاكسان. فسّر لماذا يتنافر السلكان، مبيّنًا اتجاه مجال السلك (1) عند السلك (2)، واتجاه القوة المؤثرة في السلك (2).', null, '[{"src":"qimg/phys32/c3l2-o14-opp.svg","alt":"سلكان مستقيمان رأسيان متوازيان في مستوى الورقة، السلك (1) على اليسار ويسري فيه تيار I نحو أعلى الصفحة، والسلك (2) على اليمين ويسري فيه تيار I نحو أسفل الصفحة، والمسافة بينهما d."}]'::jsonb, null, 'تطبيق', 'مقالي', 'متوسط', 'الكتاب ص 82 — القوى بين سلكين يسري فيهما تياران (الشكل 17)، والشكل 17b'),
('essay', 3, 'قال طالب: «القوة بين سلكين متوازيين يسري فيهما تياران قوة كهربائية سكونية ناتجة عن الشحنات المتحركة فيهما.» قوّم هذا القول، مبيّنًا كيف يمكن الاستدلال على أن القوة مغناطيسية، وماذا يحدث للسلك الأوسط إذا وُضع بين سلكين يسري في كل منهما تيار مساوٍ في الاتجاه نفسه وعلى البعد نفسه.', null, null, null, 'تقويم', 'مقالي', 'صعب', 'الكتاب ص 91 — السؤال 30')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O14') and x.type = v.type and x.number = v.number);
