select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'كل سلك يولّد مجالًا مغناطيسيًّا حوله، والسلك الآخر يسري فيه تيار وهو موجود في هذا المجال فيتأثر بقوة؛ وعندما يكون التياران في الاتجاه نفسه تكون القوتان نحو بعضهما فيتجاذب السلكان.', '["","التنافر يحدث عندما يكون التياران متعاكسين.","كل سلك يقع في المجال المغناطيسي للآخر ويسري فيه تيار، فيتأثر بقوة.","القوة على كل سلك عمودية على التيار المار فيه، لا في اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.397Z"}'::jsonb),
('mcq', 2, 3, 'بتطبيق القاعدة الأولى لليد اليمنى: الإبهام نحو أعلى الصفحة (اتجاه تيار السلك (1))، فتلتف الأصابع حول السلك؛ وعلى يمين السلك تتجه الأصابع نحو داخل الورقة، فالمجال عند السلك (2) داخل في الورقة.', '["هذا اتجاه المجال على يسار السلك (1)، لا على يمينه حيث يقع السلك (2).","المجال حول سلك مستقيم دوائر عمودية على اتجاه التيار، لا موازية له.","خطوط المجال حول السلك دوائر تلتف حوله، لا خطوط تخرج منه شعاعيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.398Z"}'::jsonb),
('mcq', 3, 1, 'مجال السلك (1) عند السلك (2) داخل في الورقة. بتطبيق القاعدة الثالثة لليد اليمنى على السلك (2): تُوجَّه الأصابع مع المجال (إلى الداخل) والإبهام مع التيار (إلى فوق)، فيخرج العمودي على باطن الكف إلى اليسار، أي نحو السلك (1): تجاذب.', '["هذا يحدث لو كان التياران متعاكسين (تنافر).","","القوة عمودية على التيار، فلا تكون في اتجاهه.","القوة عمودية على المجال، فلا تكون في اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.398Z"}'::jsonb),
('mcq', 4, 2, 'عندما يكون التياران في اتجاهين متعاكسين تنشأ قوة تنافر بين السلكين، فيبتعد كل منهما عن الآخر.', '["التجاذب يحدث عندما يكون التياران في الاتجاه نفسه.","كل سلك يقع في مجال الآخر ويسري فيه تيار فيتأثر بقوة.","","القوة بين السلكين على الخط الواصل بينهما (تجاذب أو تنافر)، ولا تُحدث دورانًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.398Z"}'::jsonb),
('mcq', 5, 0, 'يُحدَّد اتجاه المجال المغناطيسي حول كل سلك بالقاعدة الأولى لليد اليمنى، ثم تُطبَّق القاعدة الثالثة لليد اليمنى على السلك الآخر لتحديد اتجاه القوة المؤثرة فيه.', '["","عكس دور القاعدتين: الأولى للمجال حول السلك، والثالثة للقوة.","القاعدة الثانية تحدد قطبي المغناطيس الكهربائي (الملف اللولبي)، لا المجال حول سلك مستقيم.","القاعدة الثالثة لا تحدد اتجاه المجال حول سلك؛ يلزم أولًا تحديده بالقاعدة الأولى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-28T06:03:18.398Z"}'::jsonb),
('mcq', 6, 3, 'السلكان متعادلان كهربائيًّا، والقوة بينهما لا توجد إلا بوجود التيارين، وينقلب اتجاهها من تجاذب إلى تنافر بمجرد عكس اتجاه أحد التيارين؛ وهذا يدل على أنها ناتجة عن تأثير المجال المغناطيسي لكل تيار في التيار الآخر.', '["القوة الكهربائية السكونية أيضًا تزداد بالاقتراب، فلا يميّز ذلك بينهما.","العكس: القوة تختفي بانقطاع التيار، فلا تظهر عندها.","القوة بين السلكين قد تكون تنافرًا عندما يتعاكس التياران.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.398Z"}'::jsonb),
('mcq', 7, 2, 'التيارات في الاتجاه نفسه، فيجذب السلكُ الأيسر السلكَ الأوسط إلى اليسار، ويجذبه السلكُ الأيمن إلى اليمين بقوة مساوية لتساوي التيارات والمسافات؛ فالقوتان متعاكستان تتلاشيان.', '["السلك (3) يجذب السلك (2) بقوة مساوية في الاتجاه المعاكس، فلا تبقى محصلة نحو (1).","السلك (1) يجذب السلك (2) بقوة مساوية في الاتجاه المعاكس، فلا تبقى محصلة نحو (3).","","القوتان على السلك (2) متعاكستان فتتلاشيان، ولا تُجمعان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-28T06:03:18.399Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بالقاعدة الأولى لليد اليمنى: مجال السلك (1) عند السلك (2) (على يمينه) داخل في الورقة، ومجال السلك (2) عند السلك (1) (على يساره) خارج من الورقة. بالقاعدة الثالثة لليد اليمنى على السلك (2): الأصابع نحو داخل الورقة والإبهام نحو أعلى الصفحة، فالقوة نحو اليسار (نحو السلك 1). وعلى السلك (1): الأصابع نحو خارج الورقة والإبهام نحو أعلى الصفحة، فالقوة نحو اليمين (نحو السلك 2). القوتان نحو بعضهما فيتجاذب السلكان.', '["مجال السلك (1) عند (2) داخل الورقة","مجال السلك (2) عند (1) خارج الورقة","القوة على (2) نحو اليسار","القوة على (1) نحو اليمين، فيتجاذبان"]'::jsonb, '[]'::jsonb, '[{"element":"مجال (1) عند (2)","marks":1},{"element":"مجال (2) عند (1)","marks":1},{"element":"القوة على (2)","marks":1},{"element":"القوة على (1) والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين القاعدتين الأولى والثالثة","رسم المجال موازيًا للسلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-28T06:03:18.399Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بالقاعدة الأولى لليد اليمنى: تيار السلك (1) نحو أعلى الصفحة، فمجاله على يمينه (عند السلك 2) داخل في الورقة. بالقاعدة الثالثة لليد اليمنى على السلك (2) الذي تياره نحو أسفل الصفحة: الأصابع نحو داخل الورقة والإبهام نحو أسفل الصفحة، فالقوة نحو اليمين، أي مبتعدة عن السلك (1). وبالمثل تكون القوة على السلك (1) نحو اليسار، فيتنافر السلكان.', '["مجال (1) عند (2) داخل الورقة","القوة على (2) نحو اليمين بعيدًا عن (1)","القوة على (1) نحو اليسار، فيتنافران"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه المجال","marks":1},{"element":"اتجاه القوة على (2)","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال اتجاه التيار نفسه للسلكين","استنتاج التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-28T06:03:18.399Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. فكل سلك متعادل كهربائيًّا (فيه عدد متساوٍ من الشحنات الموجبة والسالبة)، فلا توجد قوة كهربائية سكونية محصلة. والدليل على أن القوة مغناطيسية: أنها لا تظهر إلا عند مرور التيار، وأنها تنقلب من تجاذب إلى تنافر بمجرد عكس أحد التيارين؛ ولو كانت كهربائية سكونية لكان التجاذب بين الشحنات المختلفة بغض النظر عن اتجاه حركتها. أما السلك الأوسط فيجذبه كل من السلكين الآخرين بقوتين متساويتين متعاكستين، فتكون محصلة القوى عليه صفرًا.', '["الحكم بعدم صحة القول مع ذكر تعادل السلكين","القوة توجد بوجود التيار فقط","تنقلب بعكس أحد التيارين","محصلة القوى على الأوسط صفر"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل","marks":1},{"element":"ارتباط القوة بالتيار","marks":1},{"element":"انقلاب القوة بعكس التيار","marks":1},{"element":"حالة الأسلاك الثلاثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول القول لأن التيار شحنات متحركة","جمع القوتين على السلك الأوسط بدل طرحهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.399Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
