insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C3-L2-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما دور المجالات المغناطيسية في أنبوب الأشعة المهبطية؟', null, null, '["انتزاع الإلكترونات من ذرات الكاثود","حرف الحزمة أفقيًّا ورأسيًّا","تسريع الإلكترونات وزيادة سرعتها","جعل الطبقة الفوسفورية تشع ضوءًا"]'::jsonb, 'تذكر', 'مفاهيمي', 'سهل', 'الكتاب ص 88 — أنبوب الأشعة المهبطية'),
('mcq', 2, 'في المخطط الآتي لأنبوب أشعة مهبطية، أيّ الأجزاء المرقّمة يمثل المغانط الكهربائية التي تحرف حزمة الإلكترونات؟', null, '[{"src":"qimg/phys32/c3l2-o15-crt.svg","alt":"مخطط مبسّط لأنبوب أشعة مهبطية مفرغ من الهواء: عنق ضيق على اليسار يتسع كالقمع نحو شاشة على اليمين. في العنق قطعة مرقّمة 1 تخرج منها حزمة إلكترونات (خط أحمر)، تمر الحزمة خلال صفيحتين مرقّمتين 2، ثم بين ملفين أعلى العنق وأسفله عند بداية القمع مرقّمين 3، فتنحرف الحزمة وتصطدم بالشاشة المطلية المرقّمة 4."}]'::jsonb, '["الجزء 1","الجزء 2","الجزء 3","الجزء 4"]'::jsonb, 'فهم', 'مفاهيمي', 'سهل', 'الكتاب ص 88 — أنبوب الأشعة المهبطية، الشكل 22'),
('mcq', 3, 'لماذا تُطلى شاشة أنبوب الأشعة المهبطية بطبقة فوسفورية؟', null, null, '["لأنها تشع عند اصطدام الإلكترونات بها","لأنها تحرف الإلكترونات قبل وصولها إلى الشاشة","لأنها تمنع اصطدام الإلكترونات بجزيئات الهواء","لأنها تنتزع الإلكترونات وتسرّعها نحو الشاشة"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 88 — أنبوب الأشعة المهبطية'),
('mcq', 4, 'لماذا يُفرَّغ أنبوب الأشعة المهبطية من الهواء؟', null, null, '["لزيادة القوة المغناطيسية المؤثرة في الإلكترونات","لجعل الطبقة الفوسفورية تشع بلون أوضح","لتقليل شحنة الإلكترونات قبل وصولها إلى الشاشة","لمنع اصطدام الإلكترونات بجزيئات الهواء"]'::jsonb, 'تذكر', 'مفاهيمي', 'متوسط', 'الكتاب ص 88 — أنبوب الأشعة المهبطية'),
('mcq', 5, 'تقترب حزمة إلكترونات في أنبوب أشعة مهبطية من مغناطيس قطبه الشمالي أعلى الأنبوب وقطبه الجنوبي أسفله، كما في الشكل الآتي. في أي اتجاه تنحرف الإلكترونات بالنسبة إلى شخص ينظر إلى الشاشة من أمامها؟', null, '[{"src":"qimg/phys32/c3l2-o15-poles.svg","alt":"منظر أمامي لشاشة أنبوب أشعة مهبطية كما يراها شخص يقف أمامها: القطب الشمالي N لمغناطيس فوق الشاشة والقطب الجنوبي S تحتها. في وسط الشاشة رمز • داخل دائرة حمراء مكتوب بجانبه v، يدل على أن حزمة الإلكترونات تتحرك نحو الناظر (خارجة من الورقة). يسار الشكل مكتوب «يسار» ويمينه «يمين» بالنسبة إلى الناظر."}]'::jsonb, '["نحو اليسار","نحو اليمين","نحو الأعلى","نحو الأسفل"]'::jsonb, 'تطبيق', 'مفاهيمي', 'صعب', 'الكتاب ص 91 — السؤال 26'),
('mcq', 6, 'ما الذي يُغيَّر في أنبوب الأشعة المهبطية لكي تمسح حزمة الإلكترونات الشاشة من نقطة إلى أخرى؟', null, null, '["عدد الإلكترونات المنتزعة من الكاثود","التيار في المغانط الكهربائية","سمك الطبقة الفوسفورية على الشاشة","شحنة كل إلكترون في الحزمة"]'::jsonb, 'فهم', 'مفاهيمي', 'متوسط', 'الكتاب ص 88 — أنبوب الأشعة المهبطية'),
('mcq', 7, 'إذا عُكس اتجاه التيار في المغانط الكهربائية التي تحرف الحزمة أفقيًّا في أنبوب أشعة مهبطية، فماذا يحدث لانحراف الحزمة؟', null, null, '["يتضاعف مقدار انحرافها","يتوقف انحرافها تمامًا","يصبح انحرافها رأسيًّا","ينعكس اتجاه انحرافها"]'::jsonb, 'تحليل', 'مفاهيمي', 'صعب', 'الكتاب ص 88 — أنبوب الأشعة المهبطية'),
('essay', 1, 'اشرح كيف تتكوّن الصورة على شاشة أنبوب الأشعة المهبطية، مبيّنًا دور كل من: المجالات الكهربائية، والمجالات المغناطيسية، والطبقة الفوسفورية، وتفريغ الأنبوب من الهواء.', null, '[{"src":"qimg/phys32/c3l2-o15-crt.svg","alt":"مخطط مبسّط لأنبوب أشعة مهبطية مفرغ من الهواء: عنق ضيق على اليسار يتسع كالقمع نحو شاشة على اليمين. في العنق قطعة مرقّمة 1 تخرج منها حزمة إلكترونات (خط أحمر)، تمر الحزمة خلال صفيحتين مرقّمتين 2، ثم بين ملفين أعلى العنق وأسفله عند بداية القمع مرقّمين 3، فتنحرف الحزمة وتصطدم بالشاشة المطلية المرقّمة 4."}]'::jsonb, null, 'فهم', 'مقالي', 'سهل', 'الكتاب ص 88 — أنبوب الأشعة المهبطية، وص 95'),
('essay', 2, 'تُستخدم في أنبوب الأشعة المهبطية مغانط كهربائية لا مغانط دائمة لحرف حزمة الإلكترونات. فسّر ذلك، مبيّنًا كيف يُغطّي انحراف الحزمة الشاشة كلها.', null, null, null, 'تحليل', 'مقالي', 'صعب', 'الكتاب ص 88 — أنبوب الأشعة المهبطية، الشكل 22'),
('essay', 3, 'اعتمادًا على الشكل الآتي (القطب الشمالي فوق الشاشة والجنوبي تحتها، والحزمة تتحرك نحو الناظر): (a) حدّد اتجاه انحراف حزمة الإلكترونات بالنسبة إلى الناظر، موضّحًا خطوات تطبيق القاعدة الثالثة لليد اليمنى. (b) ما اتجاه الانحراف إذا بُدِّل موضعا القطبين؟', null, '[{"src":"qimg/phys32/c3l2-o15-poles.svg","alt":"منظر أمامي لشاشة أنبوب أشعة مهبطية كما يراها شخص يقف أمامها: القطب الشمالي N لمغناطيس فوق الشاشة والقطب الجنوبي S تحتها. في وسط الشاشة رمز • داخل دائرة حمراء مكتوب بجانبه v، يدل على أن حزمة الإلكترونات تتحرك نحو الناظر (خارجة من الورقة). يسار الشكل مكتوب «يسار» ويمينه «يمين» بالنسبة إلى الناظر."}]'::jsonb, null, 'تطبيق', 'مقالي', 'متوسط', 'الكتاب ص 91 — السؤال 26')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C3-L2-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تعمل المجالات المغناطيسية على التحكم في حركة الحزمة إلى الأمام وإلى الخلف، وأفقيًّا ورأسيًّا على الشاشة، أي حرفها لتشكيل الصورة.', '["انتزاع الإلكترونات من الكاثود عمل المجالات الكهربائية.","","تسريع الإلكترونات وتجميعها عمل المجالات الكهربائية؛ والقوة المغناطيسية عمودية على السرعة فلا تزيد مقدارها.","الطبقة الفوسفورية تشع بسبب اصطدام الإلكترونات بها لا بسبب المجال المغناطيسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-28T06:03:18.400Z"}'::jsonb),
('mcq', 2, 2, 'المغانط الكهربائية للانحرافات الرأسية والأفقية توجد حول عنق الأنبوب عند بداية اتساعه، وهي الجزء 3، وتعمل مجالاتها على حرف الحزمة.', '["الجزء 1 هو الكاثود الذي تنتزع منه الإلكترونات.","الجزء 2 الأنود الذي يجمع الإلكترونات ويسرّعها بمجال كهربائي.","","الجزء 4 الشاشة المطلية بالطبقة الفوسفورية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-28T06:03:18.400Z"}'::jsonb),
('mcq', 3, 0, 'تُطلى الشاشة بطبقة فوسفورية تشع عندما تصطدم الإلكترونات بها، فتنتج الصورة.', '["","حرف الإلكترونات عمل المجالات المغناطيسية لا الطلاء.","منع التصادم بالهواء يتحقق بتفريغ الأنبوب من الهواء.","انتزاع الإلكترونات وتسريعها عمل المجالات الكهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('mcq', 4, 3, 'تتحرك الإلكترونات في الفراغ داخل الأنبوب؛ إذ تُزال جزيئات الهواء لمنع حدوث التصادمات التي تعيق حركة الحزمة.', '["القوة المغناطيسية لا تعتمد على وجود الهواء، بل على الشحنة والسرعة والمجال.","لون إشعاع الطبقة الفوسفورية لا علاقة له بتفريغ الأنبوب.","شحنة الإلكترون ثابتة لا تتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('mcq', 5, 0, 'المجال من N إلى S أي رأسيًّا إلى أسفل، والحزمة تتحرك نحو الناظر. بالقاعدة الثالثة لليد اليمنى: الأصابع إلى أسفل والإبهام نحو الناظر، فيكون الاتجاه للشحنة الموجبة نحو يمين الناظر؛ ولأن الإلكترونات سالبة تنحرف نحو اليسار.', '["","هذا اتجاه القوة على شحنة موجبة؛ نسي عكس الاتجاه للإلكترونات السالبة.","القوة عمودية على المجال الرأسي، فلا تكون إلى أعلى.","القوة عمودية على المجال الرأسي، فلا تكون إلى أسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('mcq', 6, 1, 'موضع اصطدام الحزمة بالشاشة يحدده مقدار انحرافها واتجاهه، وهما يعتمدان على المجال المغناطيسي للمغانط الكهربائية؛ فبتغيير التيار فيها يتغير المجال فتتحرك الحزمة أفقيًّا ورأسيًّا على الشاشة.', '["عدد الإلكترونات يؤثر في شدة الإضاءة لا في موضع اصطدام الحزمة.","","سمك الطلاء لا يغيّر مسار الحزمة.","شحنة الإلكترون ثابتة لا يمكن تغييرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('mcq', 7, 3, 'عكس التيار في المغناطيس الكهربائي يعكس اتجاه مجاله المغناطيسي، وبحسب القاعدة الثالثة لليد اليمنى ينعكس اتجاه القوة المؤثرة في الإلكترونات، فتنحرف الحزمة في الاتجاه الأفقي المعاكس.', '["عكس التيار يعكس اتجاه المجال لا مقداره، فلا يتضاعف الانحراف.","المجال لا ينعدم بعكس التيار، بل ينعكس اتجاهه.","عكس المجال يعكس اتجاه القوة على امتدادها نفسه، ولا يحوّلها إلى اتجاه عمودي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعمل المجالات الكهربائية على انتزاع الإلكترونات من ذرات القطب السالب (الكاثود)، وتعمل مجالات كهربائية أخرى على تجميعها وتسريعها وتركيزها في حزمة ضيقة. ثم تعمل مجالات مغناطيسية (مغانط كهربائية) على حرف الحزمة أفقيًّا ورأسيًّا فتتحرك على الشاشة. والشاشة مطلية بطبقة فوسفورية تشع عندما تصطدم الإلكترونات بها فتنتج الصورة. ويُفرَّغ الأنبوب من الهواء لمنع اصطدام الإلكترونات بجزيئات الهواء.', '["المجالات الكهربائية: انتزاع الإلكترونات وتسريعها وتركيزها","المجالات المغناطيسية: حرف الحزمة أفقيًّا ورأسيًّا","الطبقة الفوسفورية تشع عند اصطدام الإلكترونات","التفريغ يمنع التصادم مع جزيئات الهواء"]'::jsonb, '[]'::jsonb, '[{"element":"دور المجالات الكهربائية","marks":1},{"element":"دور المجالات المغناطيسية","marks":1},{"element":"دور الطبقة الفوسفورية","marks":1},{"element":"سبب التفريغ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسب تسريع الإلكترونات إلى المجال المغناطيسي","الخلط بين دوري المجالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-28T06:03:18.401Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لتشكيل صورة يجب أن تمسح الحزمة الشاشة كلها، أي أن يتغير موضع اصطدامها باستمرار أفقيًّا ورأسيًّا. والمغناطيس الدائم مجاله ثابت فيحرف الحزمة انحرافًا ثابتًا إلى نقطة واحدة. أما المغناطيس الكهربائي فيمكن تغيير مقدار مجاله واتجاهه بتغيير مقدار التيار المار فيه واتجاهه، فيتغير مقدار القوة على الإلكترونات واتجاهها، وبزوجين من المغانط (للانحراف الرأسي والأفقي) تتحرك الحزمة على الشاشة كلها.', '["يلزم تغيير موضع الحزمة باستمرار","المغناطيس الدائم مجاله ثابت","التيار في المغناطيس الكهربائي يتحكم في مقدار المجال واتجاهه","زوجان من المغانط للانحرافين الأفقي والرأسي"]'::jsonb, '[]'::jsonb, '[{"element":"الحاجة إلى المسح","marks":1},{"element":"قصور المغناطيس الدائم","marks":1},{"element":"التحكم بالتيار","marks":1},{"element":"الانحرافان الأفقي والرأسي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المغناطيس الكهربائي أقوى فقط دون ذكر إمكان التغيير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-28T06:03:18.402Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المجال من N إلى S أي رأسيًّا إلى أسفل. الأصابع إلى أسفل (المجال) والإبهام نحو الناظر (اتجاه الحركة)، فيكون العمودي على باطن الكف نحو يمين الناظر، وهذا للشحنة الموجبة؛ والإلكترونات سالبة فتنحرف نحو يسار الناظر. (b) يصبح المجال إلى أعلى فينعكس اتجاه القوة، فتنحرف الإلكترونات نحو يمين الناظر.', '["اتجاه المجال إلى أسفل","تطبيق القاعدة يعطي اليمين للشحنة الموجبة","الإلكترونات تنحرف نحو اليسار","عند تبديل القطبين تنحرف نحو اليمين"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه المجال","marks":1},{"element":"تطبيق القاعدة","marks":1},{"element":"اتجاه انحراف الإلكترونات","marks":1},{"element":"حالة تبديل القطبين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان عكس الاتجاه للإلكترونات","جعل المجال من S إلى N"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.402Z"}'::jsonb)
