('mcq', 2, 0, 'عندما يمر الرأس فوق القرص الدوّار تترتب ذرات المناطق المغناطيسية في صورة حزم، وتعتمد اتجاهات المناطق المغناطيسية على اتجاه التيار في الرأس.', '["","سرعة الدوران تحدد مكان الحزم على القرص لا اتجاه مناطقها المغناطيسية.","الجسيمات موزعة بانتظام، واتجاه مناطقها يتبع المجال لا عددها.","التخزين المغناطيسي لا يعتمد على الضوء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('mcq', 3, 3, 'تمثّل الحزمتان المغنطتان اللتان تشير أقطابهما إلى الاتجاه نفسه الرمز 0، أما اللتان تشير أقطابهما إلى اتجاهين متعاكسين فتمثّلان الرمز 1.', '["الرمز 1 تمثّله حزمتان أقطابهما في اتجاهين متعاكسين.","النظام ثنائي فيه الرمزان 0 و1 فقط.","لا يوجد في هذا الترميز حزمتان خاصتان بنهاية التسجيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('mcq', 4, 2, 'bit 1: الحزمتان نحو اليمين (الاتجاه نفسه) = 0؛ bit 2: يسار ثم يمين (متعاكستان) = 1؛ bit 3: يسار ثم يمين = 1؛ bit 4: يسار ثم يسار = 0؛ فالمخزّن 0110.', '["عكس الترميز: جعل الحزمتين المتشابهتين 1 والمتعاكستين 0.","قرأ اتجاه الحزمة الأولى من كل وحدة فقط (اليمين = 1 واليسار = 0) بدل مقارنة حزمتي الوحدة.","","قرأ اتجاه الحزمة الثانية من كل وحدة فقط (اليمين = 1 واليسار = 0) بدل مقارنة حزمتي الوحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('mcq', 5, 0, 'لاسترجاع المعلومات لا يُرسل أي تيار إلى رأس القراءة/ الكتابة، بل تعمل الحزم المغنطة على توليد تيار في الملف بطريقة الحث عندما يدور القرص تحت الرأس، وتُستشعر تغيرات اتجاه هذا التيار بالحاسوب بالنظام الثنائي.', '["","عند الاسترجاع لا يُرسل أي تيار إلى الرأس، وعكس الحزم يمحو المعلومات.","الاسترجاع مغناطيسي بالحث لا ضوئي.","الحزم لا تُعاد مغنطتها، والمعلومات تُقرأ من تغيّرات اتجاه التيار المتولد لا من جهد ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('mcq', 6, 2, 'ينعكس تيار التسجيل دائمًا عندما يبدأ رأس القراءة/ الكتابة بتسجيل وحدة المعلومة اللاحقة؛ ثم يبقى أو ينعكس داخل الوحدة بحسب الرمز المراد (0 أو 1).', '["انقطاع التيار يعني توقف الكتابة؛ أما عند الانتقال إلى الوحدة التالية فينعكس التيار.","الترميز يعتمد على اتجاه المغنطة لا على مقدار التيار.","","تيار التسجيل ينعكس دائمًا عند بدء الوحدة اللاحقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('mcq', 7, 1, 'تمثّل شفرة كل حزمتين وحدة واحدة (bit)، فيلزم لثماني وحدات $8 \times 2 = 16$ حزمة.', '["افترض أن كل وحدة تمثّلها حزمة واحدة، والصحيح حزمتان.","","قسم بدل أن يضرب: كل وحدة تحتاج حزمتين لا نصف حزمة.","جعل لكل وحدة أربع حزم بدل حزمتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-28T06:03:18.403Z"}'::jsonb),
('essay', 1, null::int, null, null, 'سطح القرص مغطى بجسيمات مغناطيسية موزعة بصورة متساوية على شريحة، ويتغير اتجاه مناطقها المغناطيسية تبعًا للتغير في المجال المغناطيسي. رأس القراءة/ الكتابة مغناطيس كهربائي (سلك ملفوف على قلب حديدي)؛ يُرسل إليه تيار كهربائي فيولّد مجالًا مغناطيسيًّا في القلب. عندما يمر الرأس فوق القرص الدوّار تترتب المناطق المغناطيسية في صورة حزم تعتمد اتجاهاتها على اتجاه التيار. كل حزمتين تمثّلان وحدة (bit): الحزمتان اللتان أقطابهما في الاتجاه نفسه تمثّلان 0، والمتعاكستان تمثّلان 1، وينعكس تيار التسجيل دائمًا عند بدء الوحدة اللاحقة.', '["سطح القرص جسيمات مغناطيسية على شريحة","الرأس مغناطيس كهربائي","المناطق تترتب في حزم حسب اتجاه التيار","حزمتان متشابهتان = 0 ومتعاكستان = 1"]'::jsonb, '[]'::jsonb, '[{"element":"سطح القرص","marks":1},{"element":"رأس القراءة/ الكتابة","marks":1},{"element":"ترتيب المناطق في حزم","marks":1},{"element":"تمثيل 0 و1","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بعناصرها الأربعة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ترميز 0 و1","وصف الرأس بأنه مغناطيس دائم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-28T06:03:18.404Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند الاسترجاع لا يُرسل أي تيار إلى رأس القراءة/ الكتابة؛ لأن إرسال تيار يولّد مجالًا قد يغيّر اتجاهات المناطق المغناطيسية فيمحو المعلومات أو يغيّرها. وبدلًا من ذلك تعمل الحزم المغنطة الموجودة على القرص على توليد تيار في ملف الرأس بطريقة الحث عندما يدور القرص تحته. وتتغير اتجاهات هذا التيار المتولد تبعًا لاتجاهات الحزم، فيستشعرها الحاسوب ويترجمها بالنظام الثنائي (صفر، واحد).', '["لا يُرسل تيار إلى الرأس لأنه قد يغيّر المغنطة","الحزم تولّد تيارًا حثيًّا في الملف عند الدوران","تغيرات اتجاه التيار تُترجم بالنظام الثنائي"]'::jsonb, '[]'::jsonb, '[{"element":"عدم إرسال تيار وتعليله","marks":1},{"element":"توليد التيار بالحث","marks":1},{"element":"الترجمة بالنظام الثنائي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرأس يرسل تيارًا للقراءة","إغفال دور دوران القرص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-28T06:03:18.404Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) bit 1: يسار ثم يمين (متعاكستان) = 1؛ bit 2: يسار ثم يسار = 0؛ bit 3: يمين ثم يسار = 1؛ bit 4: يمين ثم يمين = 0؛ فالمخزّن 1010. (b) آخر حزمة في bit 1 نحو اليمين وأول حزمة في bit 2 نحو اليسار (انعكاس)؛ آخر حزمة في bit 2 نحو اليسار وأول حزمة في bit 3 نحو اليمين (انعكاس)؛ آخر حزمة في bit 3 نحو اليسار وأول حزمة في bit 4 نحو اليمين (انعكاس). فالتيار انعكس عند بدء كل وحدة، والتسجيل يوافق القاعدة.', '["قراءة الوحدات: 1 ثم 0 ثم 1 ثم 0","مقارنة آخر حزمة في كل وحدة بأول حزمة في الوحدة التالية","الحكم بموافقة القاعدة (ثلاثة انعكاسات)"]'::jsonb, '[]'::jsonb, '[{"element":"استخراج المعلومات","marks":1},{"element":"المقارنة عند حدود الوحدات","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بعناصرها الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة الحزم عبر حدود الوحدات عند القراءة","عكس ترميز 0 و1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-28T06:03:18.404Z"}'::jsonb)
